      preferencesWindow.setAttribute('role', 'dialog');
      preferencesWindow.setAttribute('aria-labelledby', 'finder-preferences-window-title');
      preferencesWindow.setAttribute('data-finder-preferences-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';

      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(preferencesWindow);
      });

      const title = document.createElement('div');
      title.id = 'finder-preferences-window-title';
      title.className = 'finder-title';
      title.textContent = 'Finder Preferences';

      const content = document.createElement('div');
      content.className = 'finder-content finder-preferences-content';
      content.setAttribute('aria-label', 'Finder Preferences');

