    function activateTextEditCopyMenuItem() {
      closeAllMenuDropdowns();
      const selection = window.getSelection();
      const selectedText = selection ? selection.toString() : '';
      if (selectedText) {
        simulatedClipboard.text = selectedText;
      }
      document.execCommand('copy', false, null);
    }

    function activateTextEditPasteMenuItem() {
      closeAllMenuDropdowns();
      const editor = getTextEditEditor();
      if (!editor) {
        return;
      }
      editor.focus();
      const clipboardText = typeof simulatedClipboard.text === 'string'
        ? simulatedClipboard.text
        : '';
      if (clipboardText) {
        document.execCommand('insertText', false, clipboardText);
      }
    }

    function activateTextEditSelectAllMenuItem() {
      closeAllMenuDropdowns();
      const editor = getTextEditEditor();
      if (!editor) {
        return;
      }
      const range = document.createRange();
      range.selectNodeContents(editor);
      const selection = window.getSelection();
      selection.removeAllRanges();
      selection.addRange(range);
    }

