    let calculatorDisplayValue = '0';
    let calculatorAccumulator = null;
    let calculatorPendingOperator = null;
    let calculatorWaitingForOperand = false;
    let calculatorHasError = false;

    function getCalculatorWindow() {
      return document.getElementById('calculator-window');
    }

    function renderCalculatorDisplay() {
      const display = document.getElementById('calculator-display');
      if (display) {
        display.textContent = calculatorHasError ? 'Error' : calculatorDisplayValue;
      }
    }

    function resetCalculatorState() {
      calculatorDisplayValue = '0';
      calculatorAccumulator = null;
      calculatorPendingOperator = null;
      calculatorWaitingForOperand = false;
      calculatorHasError = false;
      renderCalculatorDisplay();
    }

    function enterCalculatorError() {
      calculatorHasError = true;
      calculatorAccumulator = null;
      calculatorPendingOperator = null;
      calculatorWaitingForOperand = true;
      calculatorDisplayValue = '0';
      renderCalculatorDisplay();
    }

    function formatCalculatorNumber(value) {
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        return null;
      }
      const absoluteValue = Math.abs(value);
      if (absoluteValue !== 0 && (absoluteValue >= 1e12 || absoluteValue < 1e-10)) {
        return null;
      }
      let text = String(Number(value.toFixed(10)));
      if (text === '-0') {
        text = '0';
      }
      if (text.indexOf('e') !== -1 || text.indexOf('E') !== -1) {
        return null;
      }
      if (text.length > 14) {
        text = String(Number(value.toPrecision(10)));
      }
      if (text.indexOf('e') !== -1 || text.indexOf('E') !== -1) {
        return null;
      }
      return text;
    }

    function computeCalculatorValue(leftValue, operator, rightValue) {
      if (operator === '+') {
        return leftValue + rightValue;
      }
      if (operator === '-') {
        return leftValue - rightValue;
      }
      if (operator === '*') {
        return leftValue * rightValue;
      }
      if (operator === '/') {
        if (rightValue === 0) {
          return null;
        }
        return leftValue / rightValue;
      }
      return rightValue;
    }

    function inputCalculatorDigit(digit) {
      if (calculatorHasError) {
        return;
      }
      if (calculatorWaitingForOperand) {
        calculatorDisplayValue = digit;
        calculatorWaitingForOperand = false;
        renderCalculatorDisplay();
        return;
      }
      if (calculatorDisplayValue === '0') {
        calculatorDisplayValue = digit;
      } else if (calculatorDisplayValue === '-0') {
        calculatorDisplayValue = '-' + digit;
      } else if (calculatorDisplayValue.length < 14) {
        calculatorDisplayValue += digit;
      }
      renderCalculatorDisplay();
    }

    function inputCalculatorDecimal() {
      if (calculatorHasError) {
        return;
      }
      if (calculatorWaitingForOperand) {
        calculatorDisplayValue = '0.';
        calculatorWaitingForOperand = false;
        renderCalculatorDisplay();
        return;
      }
      if (calculatorDisplayValue.indexOf('.') === -1) {
        calculatorDisplayValue += '.';
        renderCalculatorDisplay();
      }
    }

    function inputCalculatorOperator(operator) {
      if (calculatorHasError) {
        return;
      }
      const currentValue = parseFloat(calculatorDisplayValue);
      if (!Number.isFinite(currentValue)) {
        enterCalculatorError();
        return;
      }
      if (calculatorPendingOperator && !calculatorWaitingForOperand) {
        const result = computeCalculatorValue(
          calculatorAccumulator,
          calculatorPendingOperator,
          currentValue
        );
        if (result === null || !Number.isFinite(result)) {
          enterCalculatorError();
          return;
        }
        const formatted = formatCalculatorNumber(result);
        if (formatted === null) {
          enterCalculatorError();
          return;
        }
        calculatorDisplayValue = formatted;
        calculatorAccumulator = result;
        renderCalculatorDisplay();
      } else {
        calculatorAccumulator = currentValue;
      }
      calculatorPendingOperator = operator;
      calculatorWaitingForOperand = true;
    }

    function inputCalculatorEquals() {
      if (calculatorHasError) {
        return;
      }
      if (!calculatorPendingOperator || calculatorAccumulator === null) {
        calculatorWaitingForOperand = true;
        return;
      }
      const currentValue = parseFloat(calculatorDisplayValue);
      if (!Number.isFinite(currentValue)) {
        enterCalculatorError();
        return;
      }
      const result = computeCalculatorValue(
        calculatorAccumulator,
        calculatorPendingOperator,
        currentValue
      );
      if (result === null || !Number.isFinite(result)) {
        enterCalculatorError();
        return;
      }
      const formatted = formatCalculatorNumber(result);
      if (formatted === null) {
        enterCalculatorError();
        return;
      }
      calculatorDisplayValue = formatted;
      calculatorAccumulator = result;
      calculatorPendingOperator = null;
      calculatorWaitingForOperand = true;
      renderCalculatorDisplay();
    }

    function createCalculatorKey(label, className, action, ariaLabel) {
      const key = document.createElement('button');
      key.type = 'button';
      key.className = className;
      key.textContent = label;
      key.setAttribute('aria-label', ariaLabel || label);
      key.addEventListener('click', (event) => {
        event.stopPropagation();
        action();
      });
      return key;
    }

    function showCalculatorWindow() {
      recordSimulatedRecentItem(calculatorApplicationIdentity);
      const existingCalculatorWindow = getCalculatorWindow();
      if (existingCalculatorWindow && existingCalculatorWindow.isConnected) {
        focusFinderWindow(existingCalculatorWindow);
        return;
      }

      const calculatorWindow = document.createElement('section');
      calculatorWindow.id = 'calculator-window';
      calculatorWindow.className = 'finder-window calculator-window';
      calculatorWindow.setAttribute('role', 'dialog');
      calculatorWindow.setAttribute('aria-labelledby', 'calculator-window-title');
      calculatorWindow.setAttribute('data-calculator-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';

      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(calculatorWindow);
      });

      const title = document.createElement('div');
      title.id = 'calculator-window-title';
      title.className = 'finder-title';
      title.textContent = 'Calculator';

      const body = document.createElement('div');
      body.className = 'calculator-body';

      const display = document.createElement('div');
      display.id = 'calculator-display';
      display.className = 'calculator-display';
      display.setAttribute('role', 'status');
      display.setAttribute('aria-live', 'polite');
      display.setAttribute('aria-label', 'Calculator display');

      const keypad = document.createElement('div');
      keypad.className = 'calculator-keypad';
      keypad.append(
        createCalculatorKey('C', 'calculator-key calculator-key-clear', resetCalculatorState, 'Clear'),
        createCalculatorKey('÷', 'calculator-key calculator-key-operator', () => {
          inputCalculatorOperator('/');
        }, 'Divide'),
        createCalculatorKey('7', 'calculator-key', () => {
          inputCalculatorDigit('7');
        }),
        createCalculatorKey('8', 'calculator-key', () => {
          inputCalculatorDigit('8');
        }),
        createCalculatorKey('9', 'calculator-key', () => {
          inputCalculatorDigit('9');
        }),
        createCalculatorKey('×', 'calculator-key calculator-key-operator', () => {
          inputCalculatorOperator('*');
        }, 'Multiply'),
        createCalculatorKey('4', 'calculator-key', () => {
          inputCalculatorDigit('4');
        }),
        createCalculatorKey('5', 'calculator-key', () => {
          inputCalculatorDigit('5');
        }),
        createCalculatorKey('6', 'calculator-key', () => {
          inputCalculatorDigit('6');
        }),
        createCalculatorKey('−', 'calculator-key calculator-key-operator', () => {
          inputCalculatorOperator('-');
        }, 'Subtract'),
        createCalculatorKey('1', 'calculator-key', () => {
          inputCalculatorDigit('1');
        }),
        createCalculatorKey('2', 'calculator-key', () => {
          inputCalculatorDigit('2');
        }),
        createCalculatorKey('3', 'calculator-key', () => {
          inputCalculatorDigit('3');
        }),
        createCalculatorKey('+', 'calculator-key calculator-key-operator', () => {
          inputCalculatorOperator('+');
        }, 'Add'),
        createCalculatorKey('0', 'calculator-key calculator-key-zero', () => {
          inputCalculatorDigit('0');
        }),
        createCalculatorKey('.', 'calculator-key', inputCalculatorDecimal, 'Decimal point'),
        createCalculatorKey('=', 'calculator-key calculator-key-equals', inputCalculatorEquals, 'Equals')
      );

      body.append(display, keypad);
      titleBar.append(closeButton, title);
      calculatorWindow.append(titleBar, body);
      document.body.appendChild(calculatorWindow);
      enableWindowFocus(calculatorWindow);
      makeWindowDraggable(calculatorWindow, titleBar);
      renderCalculatorDisplay();
    }

