    let pagesCurrentFileSystemObject = null;
    let pagesOpenSelectedFileSystemObject = null;

    function isPagesDocument(fileSystemObject) {
      return Boolean(
        fileSystemObject &&
        fileSystemObject.type === 'file' &&
        typeof fileSystemObject.name === 'string' &&
        fileSystemObject.name.slice(-6) === '.pages'
      );
    }

    function getPagesIconMarkup() {
      return `
        <svg viewBox="0 0 72 72" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <path d="M14 8h32l12 12v42c0 2.2-1.8 4-4 4H14c-2.2 0-4-1.8-4-4V12c0-2.2 1.8-4 4-4z" fill="#fffdf8" stroke="#8a8070"/>
          <path d="M46 8v12h12z" fill="#d9d0c0" stroke="#8a8070" stroke-width=".8" stroke-linejoin="round"/>
          <path d="M18 26h30M18 33h28M18 40h24" fill="none" stroke="#c4a574" stroke-width="1.7" stroke-linecap="round"/>
          <path d="M44 46l14-20 4.2 3-14 20-5.4 1.4z" fill="#e07a28" stroke="#6a3a12" stroke-width=".7"/>
        </svg>
      `;
    }

    function getPagesWindow() {
      return document.getElementById('pages-window');
    }

    function getPagesEditor() {
      const pagesWindow = getPagesWindow();
      return pagesWindow ? pagesWindow.querySelector('.pages-editor') : null;
    }

    function updatePagesWindowTitle() {
      const pagesWindow = getPagesWindow();
      const title = pagesWindow && pagesWindow.querySelector('.finder-title');
      if (title) {
        title.textContent = pagesCurrentFileSystemObject
          ? pagesCurrentFileSystemObject.name
          : 'Untitled';
      }
    }

    function loadPagesDocument(fileSystemObject) {
      pagesCurrentFileSystemObject = fileSystemObject || null;
      const editor = getPagesEditor();
      if (editor) {
        const stored = fileSystemObject
          ? simulatedPagesDocumentBodies.get(fileSystemObject)
          : '';
        editor.innerHTML = typeof stored === 'string' ? stored : '';
      }
      updatePagesWindowTitle();
      if (fileSystemObject) {
        recordSimulatedRecentItem(fileSystemObject);
      }
    }

    function normalizePagesDocumentName(desiredName) {
      let name = typeof desiredName === 'string' ? desiredName : '';
      name = name.split('/').join('').split('\\').join('').trim();
      if (!name) {
        name = 'Untitled';
      }
      if (name.slice(-6) !== '.pages') {
        name += '.pages';
      }
      return name;
    }

    function getAvailablePagesDocumentName(parentFileSystemObject, desiredName) {
      const existingNames = new Set(
        getFileSystemObjectChildren(parentFileSystemObject).map((child) => child.name)
      );
      const baseName = normalizePagesDocumentName(desiredName);
      if (!existingNames.has(baseName)) {
        return baseName;
      }
      const withoutSuffix = baseName.slice(0, -6);
      let nextNumber = 2;
      while (existingNames.has(`${withoutSuffix} ${nextNumber}.pages`)) {
        nextNumber += 1;
      }
      return `${withoutSuffix} ${nextNumber}.pages`;
    }

    function createPagesDocumentFileSystemObject(documentName, plainTextLength) {
      return Object.freeze({
        name: documentName,
        type: 'file',
        createdAt: takeSimulatedModificationTimestamp(),
        modifiedAt: takeSimulatedModificationTimestamp(),
        size: plainTextLength || 1,
        label: simulatedNoLabel
      });
    }

    function savePagesDocumentToFileSystemObject(fileSystemObject) {
      const editor = getPagesEditor();
      if (!editor || !fileSystemObject) {
        return;
      }
      simulatedPagesDocumentBodies.set(fileSystemObject, editor.innerHTML);
      pagesCurrentFileSystemObject = fileSystemObject;
      updatePagesWindowTitle();
      recordSimulatedRecentItem(fileSystemObject);
      refreshOpenFinderWindows();
    }

    function savePagesDocument() {
      const editor = getPagesEditor();
      if (!editor) {
        return;
      }
      if (pagesCurrentFileSystemObject) {
        savePagesDocumentToFileSystemObject(pagesCurrentFileSystemObject);
        return;
      }
      const plainText = editor.innerText || editor.textContent || '';
      const newFileSystemObject = createPagesDocumentFileSystemObject(
        getAvailablePagesDocumentName(documentsFileSystemObject, 'Untitled.pages'),
        plainText.length
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      savePagesDocumentToFileSystemObject(newFileSystemObject);
    }

    function savePagesDocumentAs(desiredName) {
      const editor = getPagesEditor();
      if (!editor) {
        return;
      }
      const plainText = editor.innerText || editor.textContent || '';
      const documentName = getAvailablePagesDocumentName(
        documentsFileSystemObject,
        desiredName
      );
      if (
        pagesCurrentFileSystemObject &&
        pagesCurrentFileSystemObject.name === documentName
      ) {
        savePagesDocumentToFileSystemObject(pagesCurrentFileSystemObject);
        return;
      }
      const newFileSystemObject = createPagesDocumentFileSystemObject(
        documentName,
        plainText.length
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      savePagesDocumentToFileSystemObject(newFileSystemObject);
    }

    function applyPagesFormat(commandName) {
      const editor = getPagesEditor();
      if (!editor) {
        return;
      }
      editor.focus();
      if (typeof document.execCommand === 'function') {
        document.execCommand(commandName, false, null);
      }
    }

    function showPagesWindow(fileSystemObject) {
      recordSimulatedRecentItem(pagesApplicationIdentity);
      const existingPagesWindow = getPagesWindow();
      if (existingPagesWindow && existingPagesWindow.isConnected) {
        if (fileSystemObject) {
          loadPagesDocument(fileSystemObject);
        }
        focusFinderWindow(existingPagesWindow);
        return;
      }

      const pagesWindow = document.createElement('section');
      pagesWindow.id = 'pages-window';
      pagesWindow.className = 'finder-window pages-window';
      pagesWindow.setAttribute('role', 'dialog');
      pagesWindow.setAttribute('aria-labelledby', 'pages-window-title');
      pagesWindow.setAttribute('data-pages-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(pagesWindow);
      });
      const title = document.createElement('div');
      title.id = 'pages-window-title';
      title.className = 'finder-title';
      title.textContent = 'Untitled';
      titleBar.append(closeButton, title);

      const toolbar = document.createElement('div');
      toolbar.className = 'pages-toolbar';
      function createPagesToolbarButton(label, ariaLabel, commandName) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'pages-format-button';
        button.textContent = label;
        button.setAttribute('aria-label', ariaLabel);
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          applyPagesFormat(commandName);
        });
        return button;
      }
      toolbar.append(
        createPagesToolbarButton('B', 'Bold', 'bold'),
        createPagesToolbarButton('I', 'Italic', 'italic'),
        createPagesToolbarButton('L', 'Align Left', 'justifyLeft'),
        createPagesToolbarButton('C', 'Align Center', 'justifyCenter'),
        createPagesToolbarButton('R', 'Align Right', 'justifyRight')
      );

      const canvasWrap = document.createElement('div');
      canvasWrap.className = 'pages-canvas-wrap';
      const editor = document.createElement('div');
      editor.className = 'pages-editor';
      editor.setAttribute('contenteditable', 'true');
      editor.setAttribute('role', 'textbox');
      editor.setAttribute('aria-label', 'Pages document');
      editor.setAttribute('spellcheck', 'false');
      canvasWrap.appendChild(editor);

      pagesWindow.append(titleBar, toolbar, canvasWrap);
      document.body.appendChild(pagesWindow);
      enableWindowFocus(pagesWindow);
      makeWindowDraggable(pagesWindow, titleBar);
      if (fileSystemObject) {
        loadPagesDocument(fileSystemObject);
      } else {
        loadPagesDocument(null);
      }
      editor.focus();
    }

    function activatePagesFromDock() {
      const pagesWindow = getPagesWindow();
      if (pagesWindow && pagesWindow.isConnected) {
        recordSimulatedRecentItem(pagesApplicationIdentity);
        focusFinderWindow(pagesWindow);
        return;
      }
      showPagesWindow();
    }

