    function syncKeynoteDockContextMenuAvailability() {
      const keynoteWindow = getKeynoteWindow();
      const keynoteIsRunning = Boolean(keynoteWindow && keynoteWindow.isConnected);
      const keynoteIsVisible = keynoteIsRunning && !keynoteWindow.classList.contains('is-minimized');
      setDockContextMenuItemAvailable(keynoteDockShowAllWindowsMenuItem, keynoteIsRunning);
      setDockContextMenuItemAvailable(keynoteDockHideMenuItem, keynoteIsVisible);
      setDockContextMenuItemAvailable(keynoteDockQuitMenuItem, keynoteIsRunning);
    }

    function openKeynoteDockContextMenu(event) {
      event.preventDefault();
      event.stopPropagation();
      closeAllMenuDropdowns();
      syncKeynoteDockContextMenuAvailability();
      positionDockContextMenu(keynoteDockContextMenu, keynoteDockItem);
      keynoteDockContextMenu.hidden = false;
    }


    let numbersCurrentFileSystemObject = null;
    let numbersOpenSelectedFileSystemObject = null;
    let numbersRowCount = 8;
    let numbersColumnCount = 5;
    let numbersSelectedCell = 'A1';
    let numbersCells = {};
    let numbersUndoHistory = [];

    function isNumbersDocument(fileSystemObject) {
      return Boolean(
        fileSystemObject &&
        fileSystemObject.type === 'file' &&
        typeof fileSystemObject.name === 'string' &&
        fileSystemObject.name.slice(-8) === '.numbers'
      );
    }

    function getNumbersIconMarkup() {
      return `
        <svg viewBox="0 0 72 72" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <rect x="10" y="8" width="52" height="56" rx="8" fill="#62a322" stroke="#2d5e16"/>
          <path d="M18 24h36M18 34h36M18 44h36M18 54h36M27 18v40M36 18v40M45 18v40" fill="none" stroke="#e8f8d4" stroke-width="1.4"/>
        </svg>
      `;
    }

    function getNumbersWindow() {
      return document.getElementById('numbers-window');
    }

    function getNumbersColumnLetter(index) {
      return String.fromCharCode(65 + index);
    }

    function getNumbersCellRef(columnIndex, rowIndex) {
      return `${getNumbersColumnLetter(columnIndex)}${rowIndex + 1}`;
    }

    function parseNumbersCellRef(ref) {
      const match = /^([A-Z]+)([1-9][0-9]*)$/.exec(ref);
      if (!match) {
        return null;
      }
      const rowIndex = parseInt(match[2], 10) - 1;
      let columnIndex = 0;
      const letters = match[1];
      for (let index = 0; index < letters.length; index += 1) {
        columnIndex = columnIndex * 26 + (letters.charCodeAt(index) - 64);
      }
      return {
        columnIndex: columnIndex - 1,
        rowIndex
      };
    }

    function getNumbersCellRecord(ref) {
      return numbersCells[ref] || { raw: '', bold: false, italic: false };
    }

    function cloneNumbersCells(sourceCells) {
      const cloned = {};
      Object.keys(sourceCells).forEach((ref) => {
        const cell = sourceCells[ref];
        cloned[ref] = {
          raw: cell.raw,
          bold: Boolean(cell.bold),
          italic: Boolean(cell.italic)
        };
      });
      return cloned;
    }

    function snapshotNumbersSheet() {
      return {
        rowCount: numbersRowCount,
        columnCount: numbersColumnCount,
        selected: numbersSelectedCell,
        cells: cloneNumbersCells(numbersCells)
      };
    }

    function applyNumbersSnapshot(snapshot) {
      numbersRowCount = snapshot.rowCount;
      numbersColumnCount = snapshot.columnCount;
      numbersSelectedCell = snapshot.selected;
      numbersCells = cloneNumbersCells(snapshot.cells);
    }

    function pushNumbersUndoSnapshot() {
      numbersUndoHistory.push(snapshotNumbersSheet());
      if (numbersUndoHistory.length > 20) {
        numbersUndoHistory.shift();
      }
    }

    function resetNumbersSessionState() {
      numbersCurrentFileSystemObject = null;
      numbersOpenSelectedFileSystemObject = null;
      numbersRowCount = 8;
      numbersColumnCount = 5;
      numbersSelectedCell = 'A1';
      numbersCells = {};
      numbersUndoHistory = [];
    }

    function formatNumbersNumber(value) {
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        return 'Error';
      }
      const rounded = Math.round(value * 1e10) / 1e10;
      let text = String(rounded);
      if (text === '-0') {
        text = '0';
      }
      return text;
    }

    function expandNumbersRange(startRef, endRef) {
      const start = parseNumbersCellRef(startRef);
      const end = parseNumbersCellRef(endRef);
      if (!start || !end) {
        return [];
      }
      const refs = [];
      const minCol = Math.min(start.columnIndex, end.columnIndex);
      const maxCol = Math.max(start.columnIndex, end.columnIndex);
      const minRow = Math.min(start.rowIndex, end.rowIndex);
      const maxRow = Math.max(start.rowIndex, end.rowIndex);
      for (let rowIndex = minRow; rowIndex <= maxRow; rowIndex += 1) {
        for (let columnIndex = minCol; columnIndex <= maxCol; columnIndex += 1) {
          refs.push(getNumbersCellRef(columnIndex, rowIndex));
        }
      }
      return refs;
    }

    function evaluateNumbersArithmetic(expression) {
      let index = 0;
      function peek() {
        return expression.charAt(index);
      }
      function eat() {
        const character = expression.charAt(index);
        index += 1;
        return character;
      }
      function parseExpression() {
        let left = parseTerm();
        if (left === null) {
          return null;
        }
        while (peek() === '+' || peek() === '-') {
          const operator = eat();
          const right = parseTerm();
          if (right === null) {
            return null;
          }
          left = operator === '+' ? left + right : left - right;
        }
        return left;
      }
      function parseTerm() {
        let left = parseFactor();
        if (left === null) {
          return null;
        }
        while (peek() === '*' || peek() === '/') {
          const operator = eat();
          const right = parseFactor();
          if (right === null) {
            return null;
          }
          if (operator === '/') {
            if (right === 0) {
              return null;
            }
            left = left / right;
          } else {
            left = left * right;
          }
        }
        return left;
      }
      function parseFactor() {
        if (peek() === '(') {
          eat();
          const value = parseExpression();
          if (peek() === ')') {
            eat();
          }
          return value;
        }
        if (peek() === '-') {
          eat();
          const value = parseFactor();
          return value === null ? null : -value;
        }
        let numeric = '';
        while ((peek() >= '0' && peek() <= '9') || peek() === '.') {
          numeric += eat();
        }
        if (!numeric) {
          return null;
        }
        const value = parseFloat(numeric);
        return Number.isFinite(value) ? value : null;
      }
      const result = parseExpression();
      if (index !== expression.length) {
        return null;
      }
      return result;
    }

    function evaluateNumbersCell(ref, visiting) {
      const cell = getNumbersCellRecord(ref);
      const raw = cell.raw ? String(cell.raw) : '';
      const trimmed = raw.trim();
      if (!trimmed) {
        return 0;
      }
      if (trimmed.charAt(0) !== '=') {
        if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
          return parseFloat(trimmed);
        }
        return 0;
      }
      if (visiting[ref]) {
        return null;
      }
      visiting[ref] = true;
      const result = evaluateNumbersFormula(trimmed.slice(1), visiting);
      visiting[ref] = false;
      return result;
    }

    function evaluateNumbersFormula(formula, visiting) {
      let expression = formula.toUpperCase().split(' ').join('');
      expression = expression.replace(/SUM\(([A-Z]+[0-9]+):([A-Z]+[0-9]+)\)/g, (_, startRef, endRef) => {
        const refs = expandNumbersRange(startRef, endRef);
        let sum = 0;
        for (let index = 0; index < refs.length; index += 1) {
          const value = evaluateNumbersCell(refs[index], visiting);
          if (value === null) {
            return 'ERR';
          }
          sum += typeof value === 'number' ? value : 0;
        }
        return String(sum);
      });
      if (expression.indexOf('ERR') >= 0) {
        return null;
      }
      expression = expression.replace(/[A-Z]+[0-9]+/g, (cellRef) => {
        const value = evaluateNumbersCell(cellRef, visiting);
        if (value === null) {
          return 'ERR';
        }
        return `(${typeof value === 'number' ? value : 0})`;
      });
      if (expression.indexOf('ERR') >= 0) {
        return null;
      }
      return evaluateNumbersArithmetic(expression);
    }

    function getNumbersCellDisplay(ref) {
      const cell = getNumbersCellRecord(ref);
      const raw = cell.raw ? String(cell.raw) : '';
      if (!raw) {
        return '';
      }
      if (raw.trim().charAt(0) === '=') {
        const value = evaluateNumbersCell(ref, {});
        if (typeof value === 'number' && Number.isFinite(value)) {
          return formatNumbersNumber(value);
        }
        return 'Error';
      }
      return raw;
    }

    function setNumbersCellRaw(ref, raw, recordUndo) {
      if (recordUndo) {
        pushNumbersUndoSnapshot();
      }
      const current = getNumbersCellRecord(ref);
      if (!raw) {
        delete numbersCells[ref];
        numbersCells[ref] = {
          raw: '',
          bold: current.bold,
          italic: current.italic
        };
        if (!current.bold && !current.italic) {
          delete numbersCells[ref];
        }
        return;
      }
      numbersCells[ref] = {
        raw,
        bold: current.bold,
        italic: current.italic
      };
    }

    function updateNumbersWindowTitle() {
      const numbersWindow = getNumbersWindow();
      const title = numbersWindow && numbersWindow.querySelector('.finder-title');
      if (title) {
        title.textContent = numbersCurrentFileSystemObject
          ? numbersCurrentFileSystemObject.name
          : 'Untitled';
      }
    }

    function updateNumbersFormulaBar() {
      const refLabel = document.getElementById('numbers-selected-ref');
      const formulaInput = document.getElementById('numbers-formula-input');
      if (refLabel) {
        refLabel.textContent = numbersSelectedCell;
      }
      if (formulaInput && document.activeElement !== formulaInput) {
        formulaInput.value = getNumbersCellRecord(numbersSelectedCell).raw;
      }
    }

    function renderNumbersGrid() {
      const wrap = document.getElementById('numbers-grid-wrap');
      if (!wrap) {
        return;
      }
      const activeRef = document.activeElement && document.activeElement.getAttribute
        ? document.activeElement.getAttribute('data-cell-ref')
        : null;
      const table = document.createElement('table');
      table.className = 'numbers-grid';
      table.id = 'numbers-grid';
      const headerRow = document.createElement('tr');
      const corner = document.createElement('th');
      corner.className = 'numbers-corner';
      headerRow.appendChild(corner);
      for (let columnIndex = 0; columnIndex < numbersColumnCount; columnIndex += 1) {
        const header = document.createElement('th');
        header.className = 'numbers-col-header';
        header.textContent = getNumbersColumnLetter(columnIndex);
        headerRow.appendChild(header);
      }
      table.appendChild(headerRow);
      for (let rowIndex = 0; rowIndex < numbersRowCount; rowIndex += 1) {
        const row = document.createElement('tr');
        const rowHeader = document.createElement('th');
        rowHeader.className = 'numbers-row-header';
        rowHeader.textContent = String(rowIndex + 1);
        row.appendChild(rowHeader);
        for (let columnIndex = 0; columnIndex < numbersColumnCount; columnIndex += 1) {
          const ref = getNumbersCellRef(columnIndex, rowIndex);
          const cellRecord = getNumbersCellRecord(ref);
          const cell = document.createElement('td');
          cell.className = 'numbers-cell';
          cell.setAttribute('data-cell-ref', ref);
          if (ref === numbersSelectedCell) {
            cell.classList.add('is-selected');
          }
          const input = document.createElement('input');
          input.type = 'text';
          input.className = 'numbers-cell-input';
          input.setAttribute('data-cell-ref', ref);
          input.setAttribute('aria-label', ref);
          input.value = activeRef === ref ? cellRecord.raw : getNumbersCellDisplay(ref);
          if (cellRecord.bold) {
            input.classList.add('is-bold');
          }
          if (cellRecord.italic) {
            input.classList.add('is-italic');
          }
          input.addEventListener('focus', () => {
            numbersSelectedCell = ref;
            input.value = getNumbersCellRecord(ref).raw;
            document.querySelectorAll('td.numbers-cell').forEach((item) => {
              item.classList.toggle('is-selected', item.getAttribute('data-cell-ref') === ref);
            });
            updateNumbersFormulaBar();
          });
          input.addEventListener('blur', () => {
            if (input.value !== getNumbersCellRecord(ref).raw) {
              setNumbersCellRaw(ref, input.value, true);
            }
            renderNumbersGrid();
            updateNumbersFormulaBar();
            updateNumbersWindowTitle();
          });
          input.addEventListener('keydown', (event) => {
            if (event.key === 'Enter') {
              event.preventDefault();
              input.blur();
            }
          });
          cell.addEventListener('mousedown', () => {
            numbersSelectedCell = ref;
          });
          cell.appendChild(input);
          row.appendChild(cell);
        }
        table.appendChild(row);
      }
      wrap.replaceChildren(table);
      updateNumbersFormulaBar();
      updateNumbersWindowTitle();
      if (activeRef) {
        const nextInput = wrap.querySelector(`input[data-cell-ref="${activeRef}"]`);
        if (nextInput) {
          nextInput.focus();
        }
      }
    }

    function selectNumbersCell(ref) {
      numbersSelectedCell = ref;
      renderNumbersGrid();
    }

    function startNewNumbersSpreadsheet() {
      resetNumbersSessionState();
      renderNumbersGrid();
    }

    function loadNumbersSpreadsheet(fileSystemObject) {
      numbersCurrentFileSystemObject = fileSystemObject || null;
      const stored = fileSystemObject
        ? simulatedNumbersSpreadsheets.get(fileSystemObject)
        : null;
      if (stored) {
        numbersRowCount = stored.rowCount || 8;
        numbersColumnCount = stored.columnCount || 5;
        numbersSelectedCell = stored.selected || 'A1';
        numbersCells = cloneNumbersCells(stored.cells || {});
        numbersUndoHistory = [];
      } else {
        resetNumbersSessionState();
        numbersCurrentFileSystemObject = fileSystemObject || null;
      }
      renderNumbersGrid();
      if (fileSystemObject) {
        recordSimulatedRecentItem(fileSystemObject);
      }
    }

    function addNumbersRow() {
      pushNumbersUndoSnapshot();
      numbersRowCount += 1;
      renderNumbersGrid();
    }

    function addNumbersColumn() {
      pushNumbersUndoSnapshot();
      numbersColumnCount += 1;
      renderNumbersGrid();
    }

    function removeNumbersRow() {
      if (numbersRowCount <= 1) {
        return;
      }
      pushNumbersUndoSnapshot();
      const parsed = parseNumbersCellRef(numbersSelectedCell);
      const removedRow = parsed ? parsed.rowIndex : numbersRowCount - 1;
      const nextCells = {};
      Object.keys(numbersCells).forEach((ref) => {
        const location = parseNumbersCellRef(ref);
        if (!location) {
          return;
        }
        if (location.rowIndex === removedRow) {
          return;
        }
        const nextRow = location.rowIndex > removedRow ? location.rowIndex - 1 : location.rowIndex;
        nextCells[getNumbersCellRef(location.columnIndex, nextRow)] = numbersCells[ref];
      });
      numbersCells = nextCells;
      numbersRowCount -= 1;
      if (parsed && parsed.rowIndex >= numbersRowCount) {
        numbersSelectedCell = getNumbersCellRef(parsed.columnIndex, numbersRowCount - 1);
      }
      renderNumbersGrid();
    }

    function removeNumbersColumn() {
      if (numbersColumnCount <= 1) {
        return;
      }
      pushNumbersUndoSnapshot();
      const parsed = parseNumbersCellRef(numbersSelectedCell);
      const removedColumn = parsed ? parsed.columnIndex : numbersColumnCount - 1;
      const nextCells = {};
      Object.keys(numbersCells).forEach((ref) => {
        const location = parseNumbersCellRef(ref);
        if (!location) {
          return;
        }
        if (location.columnIndex === removedColumn) {
          return;
        }
        const nextColumn = location.columnIndex > removedColumn ? location.columnIndex - 1 : location.columnIndex;
        nextCells[getNumbersCellRef(nextColumn, location.rowIndex)] = numbersCells[ref];
      });
      numbersCells = nextCells;
      numbersColumnCount -= 1;
      if (parsed && parsed.columnIndex >= numbersColumnCount) {
        numbersSelectedCell = getNumbersCellRef(numbersColumnCount - 1, parsed.rowIndex);
      }
      renderNumbersGrid();
    }

    function toggleNumbersCellFormat(formatName) {
      pushNumbersUndoSnapshot();
      const current = getNumbersCellRecord(numbersSelectedCell);
      numbersCells[numbersSelectedCell] = {
        raw: current.raw,
        bold: formatName === 'bold' ? !current.bold : current.bold,
        italic: formatName === 'italic' ? !current.italic : current.italic
      };
      renderNumbersGrid();
    }

    function undoNumbersSheet() {
      const snapshot = numbersUndoHistory.pop();
      if (!snapshot) {
        return;
      }
      applyNumbersSnapshot(snapshot);
      renderNumbersGrid();
    }

    function getNumbersSpreadsheetPayload() {
      return Object.freeze({
        rowCount: numbersRowCount,
        columnCount: numbersColumnCount,
        selected: numbersSelectedCell,
        cells: Object.freeze(cloneNumbersCells(numbersCells))
      });
    }

    function getNumbersSpreadsheetPlainLength(payload) {
      return Object.keys(payload.cells).reduce((sum, ref) => (
        sum + String(payload.cells[ref].raw || '').length
      ), 0);
    }

    function normalizeNumbersDocumentName(desiredName) {
      let name = typeof desiredName === 'string' ? desiredName : '';
      name = name.split('/').join('').split('\\').join('').trim();
      if (!name) {
        name = 'Untitled';
      }
      if (name.slice(-8) !== '.numbers') {
        name += '.numbers';
      }
      return name;
    }

    function getAvailableNumbersDocumentName(parentFileSystemObject, desiredName) {
      const existingNames = new Set(
        getFileSystemObjectChildren(parentFileSystemObject).map((child) => child.name)
      );
      const baseName = normalizeNumbersDocumentName(desiredName);
      if (!existingNames.has(baseName)) {
        return baseName;
      }
      const withoutSuffix = baseName.slice(0, -8);
      let nextNumber = 2;
      while (existingNames.has(`${withoutSuffix} ${nextNumber}.numbers`)) {
        nextNumber += 1;
      }
      return `${withoutSuffix} ${nextNumber}.numbers`;
    }

    function createNumbersDocumentFileSystemObject(documentName, plainTextLength) {
      return Object.freeze({
        name: documentName,
        type: 'file',
        createdAt: takeSimulatedModificationTimestamp(),
        modifiedAt: takeSimulatedModificationTimestamp(),
        size: plainTextLength || 1,
        label: simulatedNoLabel
      });
    }

    function saveNumbersSpreadsheetToFileSystemObject(fileSystemObject) {
      if (!fileSystemObject) {
        return;
      }
      const payload = getNumbersSpreadsheetPayload();
      simulatedNumbersSpreadsheets.set(fileSystemObject, payload);
      numbersCurrentFileSystemObject = fileSystemObject;
      updateNumbersWindowTitle();
      recordSimulatedRecentItem(fileSystemObject);
      refreshOpenFinderWindows();
    }

    function saveNumbersSpreadsheet() {
      if (numbersCurrentFileSystemObject) {
        saveNumbersSpreadsheetToFileSystemObject(numbersCurrentFileSystemObject);
        return;
      }
      const payload = getNumbersSpreadsheetPayload();
      const newFileSystemObject = createNumbersDocumentFileSystemObject(
        getAvailableNumbersDocumentName(documentsFileSystemObject, 'Untitled.numbers'),
        getNumbersSpreadsheetPlainLength(payload)
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      saveNumbersSpreadsheetToFileSystemObject(newFileSystemObject);
    }

    function saveNumbersSpreadsheetAs(desiredName) {
      const payload = getNumbersSpreadsheetPayload();
      const documentName = getAvailableNumbersDocumentName(
        documentsFileSystemObject,
        desiredName
      );
      if (
        numbersCurrentFileSystemObject &&
        numbersCurrentFileSystemObject.name === documentName
      ) {
        saveNumbersSpreadsheetToFileSystemObject(numbersCurrentFileSystemObject);
        return;
      }
      const newFileSystemObject = createNumbersDocumentFileSystemObject(
        documentName,
        getNumbersSpreadsheetPlainLength(payload)
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      saveNumbersSpreadsheetToFileSystemObject(newFileSystemObject);
    }

    function showNumbersWindow(fileSystemObject) {
      recordSimulatedRecentItem(numbersApplicationIdentity);
      const existingNumbersWindow = getNumbersWindow();
      if (existingNumbersWindow && existingNumbersWindow.isConnected) {
        if (fileSystemObject) {
          loadNumbersSpreadsheet(fileSystemObject);
        }
        focusFinderWindow(existingNumbersWindow);
        return;
      }

      const numbersWindow = document.createElement('section');
      numbersWindow.id = 'numbers-window';
      numbersWindow.className = 'finder-window numbers-window';
      numbersWindow.setAttribute('role', 'dialog');
      numbersWindow.setAttribute('aria-labelledby', 'numbers-window-title');
      numbersWindow.setAttribute('data-numbers-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(numbersWindow);
      });
      const title = document.createElement('div');
      title.id = 'numbers-window-title';
      title.className = 'finder-title';
      title.textContent = 'Untitled';
      titleBar.append(closeButton, title);

      const toolbar = document.createElement('div');
      toolbar.className = 'numbers-toolbar';
      function createNumbersToolbarButton(label, ariaLabel, action) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'numbers-format-button';
        button.textContent = label;
        button.setAttribute('aria-label', ariaLabel);
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          action();
        });
        return button;
      }
      toolbar.append(
        createNumbersToolbarButton('B', 'Bold', () => {
          toggleNumbersCellFormat('bold');
        }),
        createNumbersToolbarButton('I', 'Italic', () => {
          toggleNumbersCellFormat('italic');
        }),
        createNumbersToolbarButton('+ Row', 'Add Row', addNumbersRow),
        createNumbersToolbarButton('+ Col', 'Add Column', addNumbersColumn)
      );

      const formulaBar = document.createElement('div');
      formulaBar.className = 'numbers-formula-bar';
      const refLabel = document.createElement('div');
      refLabel.id = 'numbers-selected-ref';
      refLabel.className = 'numbers-selected-ref';
      refLabel.textContent = 'A1';
      const formulaInput = document.createElement('input');
      formulaInput.type = 'text';
      formulaInput.id = 'numbers-formula-input';
      formulaInput.className = 'numbers-formula-input';
      formulaInput.setAttribute('aria-label', 'Formula');
      formulaInput.addEventListener('click', (event) => {
        event.stopPropagation();
      });
      formulaInput.addEventListener('blur', () => {
        if (formulaInput.value !== getNumbersCellRecord(numbersSelectedCell).raw) {
          setNumbersCellRaw(numbersSelectedCell, formulaInput.value, true);
          renderNumbersGrid();
        }
      });
      formulaInput.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
          event.preventDefault();
          formulaInput.blur();
        }
      });
      formulaBar.append(refLabel, formulaInput);

      const gridWrap = document.createElement('div');
      gridWrap.className = 'numbers-grid-wrap';
      gridWrap.id = 'numbers-grid-wrap';

      numbersWindow.append(titleBar, toolbar, formulaBar, gridWrap);
      document.body.appendChild(numbersWindow);
      enableWindowFocus(numbersWindow);
      makeWindowDraggable(numbersWindow, titleBar);
      if (fileSystemObject) {
        loadNumbersSpreadsheet(fileSystemObject);
      } else {
        startNewNumbersSpreadsheet();
      }
    }

    function activateNumbersFromDock() {
      const numbersWindow = getNumbersWindow();
      if (numbersWindow && numbersWindow.isConnected) {
        recordSimulatedRecentItem(numbersApplicationIdentity);
        focusFinderWindow(numbersWindow);
        return;
      }
      showNumbersWindow();
    }

    function hideNumbersWindow() {
      const numbersWindow = getNumbersWindow();
      if (numbersWindow && numbersWindow.isConnected && !numbersWindow.classList.contains('is-minimized')) {
        minimizeFinderWindow(numbersWindow);
      }
    }

    function quitNumbersWindow() {
      const numbersWindow = getNumbersWindow();
      if (numbersWindow && numbersWindow.isConnected) {
        closeFinderWindow(numbersWindow);
      }
    }

    function showAboutNumbersWindow() {
      const existingAboutWindow = document.getElementById('about-numbers-window');
      if (existingAboutWindow && existingAboutWindow.isConnected) {
        focusFinderWindow(existingAboutWindow);
        return;
      }
      const aboutWindow = document.createElement('section');
      aboutWindow.id = 'about-numbers-window';
      aboutWindow.className = 'finder-window about-numbers-window';
      aboutWindow.setAttribute('role', 'dialog');
      aboutWindow.setAttribute('aria-labelledby', 'about-numbers-window-title');
      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(aboutWindow);
      });
      const title = document.createElement('div');
      title.id = 'about-numbers-window-title';
      title.className = 'finder-title';
      title.textContent = 'About Numbers';
      const content = document.createElement('div');
      content.className = 'finder-content about-finder-content';
      const heading = document.createElement('div');
      heading.className = 'about-finder-heading';
      heading.textContent = 'Numbers';
      const copy = document.createElement('p');
      copy.className = 'about-finder-copy';
      copy.textContent = 'A simulated Mac OS X Tiger-style Numbers spreadsheet.';
      content.append(heading, copy);
      titleBar.append(closeButton, title);
      aboutWindow.append(titleBar, content);
      document.body.appendChild(aboutWindow);
      enableWindowFocus(aboutWindow);
      makeWindowDraggable(aboutWindow, titleBar);
    }

    function collectNumbersDocuments() {
      const collected = [];
      collectSimulatedFileSystemHierarchy(macintoshHDFileSystemObject, collected);
      collectSimulatedFileSystemHierarchy(homeFileSystemObject, collected);
      return collected.filter((fileSystemObject) => isNumbersDocument(fileSystemObject));
    }

    function showNumbersOpenWindow() {
      const existingOpenWindow = document.getElementById('numbers-open-window');
      if (existingOpenWindow && existingOpenWindow.isConnected) {
        focusFinderWindow(existingOpenWindow);
        return;
      }
      const openWindow = document.createElement('section');
      openWindow.id = 'numbers-open-window';
      openWindow.className = 'finder-window numbers-open-window';
      openWindow.setAttribute('role', 'dialog');
      openWindow.setAttribute('aria-labelledby', 'numbers-open-window-title');
      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(openWindow);
      });
      const title = document.createElement('div');
      title.id = 'numbers-open-window-title';
      title.className = 'finder-title';
      title.textContent = 'Open';
      const content = document.createElement('div');
      content.className = 'finder-content numbers-open-content';
      const list = document.createElement('div');
      list.className = 'numbers-open-list';
      list.setAttribute('role', 'listbox');
      list.setAttribute('aria-label', 'Numbers spreadsheets');
      const files = collectNumbersDocuments();
      numbersOpenSelectedFileSystemObject = files[0] || null;
      files.forEach((fileSystemObject, fileIndex) => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'numbers-open-file';
        item.textContent = fileSystemObject.name;
        item.setAttribute('role', 'option');
        if (fileIndex === 0) {
          item.classList.add('is-selected');
        }
        item.addEventListener('click', (event) => {
          event.stopPropagation();
          numbersOpenSelectedFileSystemObject = fileSystemObject;
          list.querySelectorAll('.numbers-open-file').forEach((fileItem) => {
            fileItem.classList.toggle('is-selected', fileItem === item);
          });
        });
        item.addEventListener('dblclick', (event) => {
          event.stopPropagation();
          numbersOpenSelectedFileSystemObject = fileSystemObject;
          closeFinderWindow(openWindow);
          showNumbersWindow(fileSystemObject);
        });
        list.appendChild(item);
      });
      const actions = document.createElement('div');
      actions.className = 'numbers-open-actions';
      const openButton = document.createElement('button');
      openButton.type = 'button';
      openButton.className = 'numbers-format-button';
      openButton.textContent = 'Open';
      openButton.addEventListener('click', (event) => {
        event.stopPropagation();
        const selectedFileSystemObject = numbersOpenSelectedFileSystemObject;
        closeFinderWindow(openWindow);
        if (selectedFileSystemObject) {
          showNumbersWindow(selectedFileSystemObject);
        }
      });
      actions.appendChild(openButton);
      content.append(list, actions);
      titleBar.append(closeButton, title);
      openWindow.append(titleBar, content);
      document.body.appendChild(openWindow);
      enableWindowFocus(openWindow);
      makeWindowDraggable(openWindow, titleBar);
    }

    function showNumbersSaveAsWindow() {
      const existingSaveAsWindow = document.getElementById('numbers-save-as-window');
      if (existingSaveAsWindow && existingSaveAsWindow.isConnected) {
        focusFinderWindow(existingSaveAsWindow);
        return;
      }
      const saveAsWindow = document.createElement('section');
      saveAsWindow.id = 'numbers-save-as-window';
      saveAsWindow.className = 'finder-window numbers-save-as-window';
      saveAsWindow.setAttribute('role', 'dialog');
      saveAsWindow.setAttribute('aria-labelledby', 'numbers-save-as-window-title');
      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(saveAsWindow);
      });
      const title = document.createElement('div');
      title.id = 'numbers-save-as-window-title';
      title.className = 'finder-title';
      title.textContent = 'Save As';
      const content = document.createElement('div');
      content.className = 'finder-content numbers-save-as-content';
      const label = document.createElement('div');
      label.className = 'numbers-save-as-label';
      label.textContent = 'Save as:';
      const nameField = document.createElement('input');
      nameField.type = 'text';
      nameField.id = 'numbers-save-as-name';
      nameField.className = 'numbers-save-as-name';
      nameField.setAttribute('aria-label', 'Spreadsheet name');
      nameField.value = numbersCurrentFileSystemObject
        ? numbersCurrentFileSystemObject.name
        : 'Untitled.numbers';
      nameField.addEventListener('click', (event) => {
        event.stopPropagation();
      });
      nameField.addEventListener('keydown', (event) => {
        event.stopPropagation();
        if (event.key === 'Enter') {
          event.preventDefault();
          const nextName = nameField.value;
          closeFinderWindow(saveAsWindow);
          saveNumbersSpreadsheetAs(nextName);
        }
      });
      const actions = document.createElement('div');
      actions.className = 'numbers-save-as-actions';
      const saveButton = document.createElement('button');
      saveButton.type = 'button';
      saveButton.className = 'numbers-format-button';
      saveButton.id = 'numbers-save-as-button';
      saveButton.textContent = 'Save';
      saveButton.addEventListener('click', (event) => {
        event.stopPropagation();
        const nextName = nameField.value;
        closeFinderWindow(saveAsWindow);
        saveNumbersSpreadsheetAs(nextName);
      });
      actions.appendChild(saveButton);
      content.append(label, nameField, actions);
      titleBar.append(closeButton, title);
      saveAsWindow.append(titleBar, content);
      document.body.appendChild(saveAsWindow);
      enableWindowFocus(saveAsWindow);
      makeWindowDraggable(saveAsWindow, titleBar);
      nameField.focus();
      nameField.select();
    }

