    function syncNumbersDockContextMenuAvailability() {
      const numbersWindow = getNumbersWindow();
      const numbersIsRunning = Boolean(numbersWindow && numbersWindow.isConnected);
      const numbersIsVisible = numbersIsRunning && !numbersWindow.classList.contains('is-minimized');
      setDockContextMenuItemAvailable(numbersDockShowAllWindowsMenuItem, numbersIsRunning);
      setDockContextMenuItemAvailable(numbersDockHideMenuItem, numbersIsVisible);
      setDockContextMenuItemAvailable(numbersDockQuitMenuItem, numbersIsRunning);
    }

    function openNumbersDockContextMenu(event) {
      event.preventDefault();
      event.stopPropagation();
      closeAllMenuDropdowns();
      syncNumbersDockContextMenuAvailability();
      positionDockContextMenu(numbersDockContextMenu, numbersDockItem);
      numbersDockContextMenu.hidden = false;
    }


    let iPhotoPhotos = [];
    let iPhotoAlbums = [];
    let iPhotoSelectedIds = [];
    let iPhotoSource = 'library';
    let iPhotoUndoHistory = [];
    let iPhotoClipboardPhotoIds = [];
    let nextIPhotoPhotoSequence = 1;
    let nextIPhotoAlbumSequence = 1;

    function getDefaultIPhotoPhotos() {
      return [
        { id: 'iphoto-photo-aqua', name: 'Aqua Afternoon', event: 'Tiger Days', rotation: 0, inTrash: false, palette: 0 },
        { id: 'iphoto-photo-stripe', name: 'Tiger Stripe', event: 'Tiger Days', rotation: 0, inTrash: false, palette: 1 },
        { id: 'iphoto-photo-graphite', name: 'Graphite Sky', event: 'Tiger Days', rotation: 0, inTrash: false, palette: 2 },
        { id: 'iphoto-photo-dockside', name: 'Dockside', event: 'Desktop Life', rotation: 0, inTrash: false, palette: 3 },
        { id: 'iphoto-photo-spotlight', name: 'Spotlight', event: 'Desktop Life', rotation: 0, inTrash: false, palette: 4 },
        { id: 'iphoto-photo-safari', name: 'Safari Wind', event: 'Desktop Life', rotation: 0, inTrash: false, palette: 5 }
      ];
    }

    function resetIPhotoSessionState() {
      iPhotoPhotos = getDefaultIPhotoPhotos();
      iPhotoAlbums = [];
      iPhotoSelectedIds = [];
      iPhotoSource = 'library';
      iPhotoUndoHistory = [];
      iPhotoClipboardPhotoIds = [];
      nextIPhotoPhotoSequence = 1;
      nextIPhotoAlbumSequence = 1;
    }

    function getIPhotoWindow() {
      return document.getElementById('iphoto-window');
    }

    function cloneIPhotoPhotos(photos) {
      return photos.map((photo) => ({
        id: photo.id,
        name: photo.name,
        event: photo.event,
        rotation: photo.rotation,
        inTrash: Boolean(photo.inTrash),
        palette: photo.palette
      }));
    }

    function cloneIPhotoAlbums(albums) {
      return albums.map((album) => ({
        id: album.id,
        name: album.name,
        photoIds: album.photoIds.slice()
      }));
    }

    function snapshotIPhotoLibrary() {
      return {
        photos: cloneIPhotoPhotos(iPhotoPhotos),
        albums: cloneIPhotoAlbums(iPhotoAlbums),
        selectedIds: iPhotoSelectedIds.slice(),
        source: iPhotoSource
      };
    }

    function applyIPhotoSnapshot(snapshot) {
      iPhotoPhotos = cloneIPhotoPhotos(snapshot.photos);
      iPhotoAlbums = cloneIPhotoAlbums(snapshot.albums);
      iPhotoSelectedIds = snapshot.selectedIds.slice();
      iPhotoSource = snapshot.source;
    }

    function pushIPhotoUndoSnapshot() {
      iPhotoUndoHistory.push(snapshotIPhotoLibrary());
      if (iPhotoUndoHistory.length > 20) {
        iPhotoUndoHistory.shift();
      }
    }

    function getIPhotoPhotoById(photoId) {
      return iPhotoPhotos.find((photo) => photo.id === photoId) || null;
    }

    function getIPhotoAlbumById(albumId) {
      return iPhotoAlbums.find((album) => album.id === albumId) || null;
    }

    function getVisibleIPhotoPhotos() {
      if (iPhotoSource === 'trash') {
        return iPhotoPhotos.filter((photo) => photo.inTrash);
      }
      if (iPhotoSource.indexOf('album:') === 0) {
        const album = getIPhotoAlbumById(iPhotoSource.slice(6));
        if (!album) {
          return [];
        }
        return album.photoIds
          .map((photoId) => getIPhotoPhotoById(photoId))
          .filter((photo) => photo && !photo.inTrash);
      }
      return iPhotoPhotos.filter((photo) => !photo.inTrash);
    }

    function getIPhotoPhotoMarkup(photo) {
      const palettes = [
        ['#4ec8f4', '#07589c'],
        ['#f4a04a', '#a4161a'],
        ['#c8c8c8', '#4a4a4a'],
        ['#d5dbe1', '#5d6974'],
        ['#ffe36a', '#3a2a08'],
        ['#6ec4f4', '#163a68']
      ];
      const palette = palettes[photo.palette % palettes.length];
      const gradientId = `iphotoArt${photo.id}`;
      return `
        <svg viewBox="0 0 160 120" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <defs>
            <linearGradient id="${gradientId}" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stop-color="${palette[0]}"/>
              <stop offset="1" stop-color="${palette[1]}"/>
            </linearGradient>
          </defs>
          <g transform="rotate(${photo.rotation} 80 60)">
            <rect width="160" height="120" fill="url(#${gradientId})"/>
            <ellipse cx="118" cy="28" rx="16" ry="16" fill="#fff4c4" opacity="0.9"/>
            <path d="M0 78c28-18 54-8 80 2 26 10 52 8 80-8v48H0z" fill="rgba(0,0,0,0.22)"/>
          </g>
        </svg>
      `;
    }

    function renderIPhotoSidebar() {
      const sidebar = document.getElementById('iphoto-sidebar');
      if (!sidebar) {
        return;
      }
      sidebar.replaceChildren();
      function addHeading(label) {
        const heading = document.createElement('div');
        heading.className = 'iphoto-sidebar-heading';
        heading.textContent = label;
        sidebar.appendChild(heading);
      }
      function addSource(sourceId, label) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'iphoto-source';
        button.setAttribute('data-iphoto-source', sourceId);
        button.textContent = label;
        const isSelected = iPhotoSource === sourceId;
        button.classList.toggle('is-selected', isSelected);
        button.setAttribute('aria-selected', String(isSelected));
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          iPhotoSource = sourceId;
          iPhotoSelectedIds = [];
          renderIPhotoLibrary();
        });
        sidebar.appendChild(button);
      }
      addHeading('LIBRARY');
      addSource('library', 'Library');
      addSource('events', 'Events');
      addHeading('ALBUMS');
      iPhotoAlbums.forEach((album) => {
        addSource(`album:${album.id}`, album.name);
      });
      addHeading('TRASH');
      addSource('trash', 'Trash');
    }

    function renderIPhotoGrid() {
      const grid = document.getElementById('iphoto-grid');
      if (!grid) {
        return;
      }
      const photos = getVisibleIPhotoPhotos();
      grid.replaceChildren();
      if (photos.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'iphoto-empty';
        empty.id = 'iphoto-empty';
        empty.textContent = iPhotoSource === 'trash' ? 'iPhoto Trash is empty.' : 'No photos in this view.';
        grid.appendChild(empty);
        return;
      }
      photos.forEach((photo) => {
        const thumb = document.createElement('button');
        thumb.type = 'button';
        thumb.className = 'iphoto-thumb';
        thumb.setAttribute('data-photo-id', photo.id);
        thumb.setAttribute('aria-label', photo.name);
        const isSelected = iPhotoSelectedIds.indexOf(photo.id) >= 0;
        thumb.classList.toggle('is-selected', isSelected);
        const art = document.createElement('div');
        art.className = 'iphoto-thumb-art';
        art.innerHTML = getIPhotoPhotoMarkup(photo);
        const name = document.createElement('div');
        name.className = 'iphoto-thumb-name';
        name.textContent = iPhotoSource === 'events' ? `${photo.name} · ${photo.event}` : photo.name;
        thumb.append(art, name);
        thumb.addEventListener('click', (event) => {
          event.stopPropagation();
          if (event.shiftKey && iPhotoSelectedIds.length > 0) {
            if (iPhotoSelectedIds.indexOf(photo.id) < 0) {
              iPhotoSelectedIds = iPhotoSelectedIds.concat([photo.id]);
            }
          } else {
            iPhotoSelectedIds = [photo.id];
          }
          renderIPhotoLibrary();
        });
        thumb.addEventListener('dblclick', (event) => {
          event.stopPropagation();
          iPhotoSelectedIds = [photo.id];
          renderIPhotoLibrary();
        });
        grid.appendChild(thumb);
      });
    }

    function renderIPhotoViewer() {
      const viewer = document.getElementById('iphoto-viewer');
      if (!viewer) {
        return;
      }
      const selectedPhoto = iPhotoSelectedIds.length === 1
        ? getIPhotoPhotoById(iPhotoSelectedIds[0])
        : null;
      const art = viewer.querySelector('#iphoto-viewer-art');
      const title = viewer.querySelector('#iphoto-viewer-title');
      const detail = viewer.querySelector('#iphoto-viewer-detail');
      const status = viewer.querySelector('#iphoto-status');
      if (art) {
        art.innerHTML = selectedPhoto ? getIPhotoPhotoMarkup(selectedPhoto) : '';
      }
      if (title) {
        title.textContent = selectedPhoto ? selectedPhoto.name : 'Select a photo';
      }
      if (detail) {
        detail.textContent = selectedPhoto
          ? `${selectedPhoto.event} · ${selectedPhoto.rotation}°`
          : '';
      }
      if (status) {
        status.textContent = `${getVisibleIPhotoPhotos().length} photos`;
      }
    }

    function renderIPhotoLibrary() {
      renderIPhotoSidebar();
      renderIPhotoGrid();
      renderIPhotoViewer();
    }

    function getCurrentIPhotoAlbum() {
      if (iPhotoSource.indexOf('album:') !== 0) {
        return null;
      }
      return getIPhotoAlbumById(iPhotoSource.slice(6));
    }

    function createIPhotoAlbum() {
      pushIPhotoUndoSnapshot();
      const existingNames = new Set(iPhotoAlbums.map((album) => album.name));
      let name = 'Untitled Album';
      let nextNumber = 2;
      while (existingNames.has(name)) {
        name = `Untitled Album ${nextNumber}`;
        nextNumber += 1;
      }
      const album = {
        id: `iphoto-album-${nextIPhotoAlbumSequence}`,
        name,
        photoIds: iPhotoSelectedIds.filter((photoId) => {
          const photo = getIPhotoPhotoById(photoId);
          return photo && !photo.inTrash;
        })
      };
      nextIPhotoAlbumSequence += 1;
      iPhotoAlbums.push(album);
      iPhotoSource = `album:${album.id}`;
      renderIPhotoLibrary();
    }

    function importSimulatedIPhotoPhotos() {
      pushIPhotoUndoSnapshot();
      const photo = {
        id: `iphoto-photo-imported-${nextIPhotoPhotoSequence}`,
        name: `Imported Photo ${nextIPhotoPhotoSequence}`,
        event: 'Imported',
        rotation: 0,
        inTrash: false,
        palette: nextIPhotoPhotoSequence % 6
      };
      nextIPhotoPhotoSequence += 1;
      iPhotoPhotos.push(photo);
      iPhotoSelectedIds = [photo.id];
      if (iPhotoSource === 'trash') {
        iPhotoSource = 'library';
      }
      const album = getCurrentIPhotoAlbum();
      if (album && album.photoIds.indexOf(photo.id) < 0) {
        album.photoIds.push(photo.id);
      }
      renderIPhotoLibrary();
    }

    function rotateIPhotoSelectedPhotos(amount) {
      if (iPhotoSelectedIds.length === 0) {
        return;
      }
      pushIPhotoUndoSnapshot();
      iPhotoSelectedIds.forEach((photoId) => {
        const photo = getIPhotoPhotoById(photoId);
        if (photo) {
          photo.rotation = (photo.rotation + amount + 360) % 360;
        }
      });
      renderIPhotoLibrary();
    }

    function trashIPhotoSelectedPhotos() {
      if (iPhotoSelectedIds.length === 0) {
        return;
      }
      pushIPhotoUndoSnapshot();
      iPhotoSelectedIds.forEach((photoId) => {
        const photo = getIPhotoPhotoById(photoId);
        if (photo) {
          photo.inTrash = true;
        }
        iPhotoAlbums.forEach((album) => {
          album.photoIds = album.photoIds.filter((id) => id !== photoId);
        });
      });
      iPhotoSelectedIds = [];
      renderIPhotoLibrary();
    }

    function addIPhotoSelectedPhotosToAlbum() {
      let album = getCurrentIPhotoAlbum();
      if (!album) {
        if (iPhotoAlbums.length === 0) {
          createIPhotoAlbum();
          return;
        }
        album = iPhotoAlbums[iPhotoAlbums.length - 1];
      }
      pushIPhotoUndoSnapshot();
      iPhotoSelectedIds.forEach((photoId) => {
        const photo = getIPhotoPhotoById(photoId);
        if (photo && !photo.inTrash && album.photoIds.indexOf(photoId) < 0) {
          album.photoIds.push(photoId);
        }
      });
      iPhotoSource = `album:${album.id}`;
      renderIPhotoLibrary();
    }

    function removeIPhotoSelectedPhotosFromAlbum() {
      const album = getCurrentIPhotoAlbum();
      if (!album || iPhotoSelectedIds.length === 0) {
        return;
      }
      pushIPhotoUndoSnapshot();
      album.photoIds = album.photoIds.filter((photoId) => iPhotoSelectedIds.indexOf(photoId) < 0);
      iPhotoSelectedIds = [];
      renderIPhotoLibrary();
    }

    function undoIPhotoLibrary() {
      const snapshot = iPhotoUndoHistory.pop();
      if (!snapshot) {
        return;
      }
      applyIPhotoSnapshot(snapshot);
      renderIPhotoLibrary();
    }

    function copyIPhotoSelection() {
      iPhotoClipboardPhotoIds = iPhotoSelectedIds.slice();
      const names = iPhotoSelectedIds
        .map((photoId) => getIPhotoPhotoById(photoId))
        .filter(Boolean)
        .map((photo) => photo.name);
      if (names.length > 0) {
        simulatedClipboard.text = names.join(', ');
      }
    }

    function cutIPhotoSelection() {
      copyIPhotoSelection();
      const album = getCurrentIPhotoAlbum();
      if (album) {
        removeIPhotoSelectedPhotosFromAlbum();
        return;
      }
      trashIPhotoSelectedPhotos();
    }

    function pasteIPhotoSelection() {
      if (iPhotoClipboardPhotoIds.length === 0) {
        return;
      }
      let album = getCurrentIPhotoAlbum();
      if (!album) {
        if (iPhotoAlbums.length === 0) {
          createIPhotoAlbum();
          album = getCurrentIPhotoAlbum();
        } else {
          album = iPhotoAlbums[iPhotoAlbums.length - 1];
          iPhotoSource = `album:${album.id}`;
        }
      }
      if (!album) {
        return;
      }
      pushIPhotoUndoSnapshot();
      iPhotoClipboardPhotoIds.forEach((photoId) => {
        const photo = getIPhotoPhotoById(photoId);
        if (photo && !photo.inTrash && album.photoIds.indexOf(photoId) < 0) {
          album.photoIds.push(photoId);
        }
      });
      renderIPhotoLibrary();
    }

    function selectAllIPhotoPhotos() {
      iPhotoSelectedIds = getVisibleIPhotoPhotos().map((photo) => photo.id);
      renderIPhotoLibrary();
    }

    function showIPhotoWindow() {
      recordSimulatedRecentItem(iPhotoApplicationIdentity);
      const existingIPhotoWindow = getIPhotoWindow();
      if (existingIPhotoWindow && existingIPhotoWindow.isConnected) {
        focusFinderWindow(existingIPhotoWindow);
        return;
      }
      if (iPhotoPhotos.length === 0) {
        resetIPhotoSessionState();
      }

      const iPhotoWindow = document.createElement('section');
      iPhotoWindow.id = 'iphoto-window';
      iPhotoWindow.className = 'finder-window iphoto-window';
      iPhotoWindow.setAttribute('role', 'dialog');
      iPhotoWindow.setAttribute('aria-labelledby', 'iphoto-window-title');
      iPhotoWindow.setAttribute('data-iphoto-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(iPhotoWindow);
      });
      const title = document.createElement('div');
      title.id = 'iphoto-window-title';
      title.className = 'finder-title';
      title.textContent = 'iPhoto';
      titleBar.append(closeButton, title);

      const toolbar = document.createElement('div');
      toolbar.className = 'iphoto-toolbar';
      function createIPhotoToolButton(label, ariaLabel, action) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'iphoto-tool-button';
        button.textContent = label;
        button.setAttribute('aria-label', ariaLabel);
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          action();
        });
        return button;
      }
      toolbar.append(
        createIPhotoToolButton('Album', 'New Album', createIPhotoAlbum),
        createIPhotoToolButton('Import', 'Import Photos', importSimulatedIPhotoPhotos),
        createIPhotoToolButton('⟲', 'Rotate Left', () => {
          rotateIPhotoSelectedPhotos(-90);
        }),
        createIPhotoToolButton('⟳', 'Rotate Right', () => {
          rotateIPhotoSelectedPhotos(90);
        })
      );

      const body = document.createElement('div');
      body.className = 'iphoto-body';
      const sidebar = document.createElement('div');
      sidebar.className = 'iphoto-sidebar';
      sidebar.id = 'iphoto-sidebar';
      const main = document.createElement('div');
      main.className = 'iphoto-main';
      const grid = document.createElement('div');
      grid.className = 'iphoto-grid';
      grid.id = 'iphoto-grid';
      const viewer = document.createElement('div');
      viewer.className = 'iphoto-viewer';
      viewer.id = 'iphoto-viewer';
      const viewerArt = document.createElement('div');
      viewerArt.className = 'iphoto-viewer-art';
      viewerArt.id = 'iphoto-viewer-art';
      const viewerCopy = document.createElement('div');
      viewerCopy.className = 'iphoto-viewer-copy';
      const viewerTitle = document.createElement('div');
      viewerTitle.className = 'iphoto-viewer-title';
      viewerTitle.id = 'iphoto-viewer-title';
      const viewerDetail = document.createElement('div');
      viewerDetail.className = 'iphoto-viewer-detail';
      viewerDetail.id = 'iphoto-viewer-detail';
      viewerCopy.append(viewerTitle, viewerDetail);
      const status = document.createElement('div');
      status.className = 'iphoto-status';
      status.id = 'iphoto-status';
      viewer.append(viewerArt, viewerCopy, status);
      main.append(grid, viewer);
      body.append(sidebar, main);

      iPhotoWindow.append(titleBar, toolbar, body);
      document.body.appendChild(iPhotoWindow);
      enableWindowFocus(iPhotoWindow);
      makeWindowDraggable(iPhotoWindow, titleBar);
      renderIPhotoLibrary();
    }

    function activateIPhotoFromDock() {
      const iPhotoWindow = getIPhotoWindow();
      if (iPhotoWindow && iPhotoWindow.isConnected) {
        recordSimulatedRecentItem(iPhotoApplicationIdentity);
        focusFinderWindow(iPhotoWindow);
        return;
      }
      showIPhotoWindow();
    }

    function hideIPhotoWindow() {
      const iPhotoWindow = getIPhotoWindow();
      if (iPhotoWindow && iPhotoWindow.isConnected && !iPhotoWindow.classList.contains('is-minimized')) {
        minimizeFinderWindow(iPhotoWindow);
      }
    }

    function quitIPhotoWindow() {
      const iPhotoWindow = getIPhotoWindow();
      if (iPhotoWindow && iPhotoWindow.isConnected) {
        closeFinderWindow(iPhotoWindow);
      }
    }

    function showAboutIPhotoWindow() {
      const existingAboutWindow = document.getElementById('about-iphoto-window');
      if (existingAboutWindow && existingAboutWindow.isConnected) {
        focusFinderWindow(existingAboutWindow);
        return;
      }
      const aboutWindow = document.createElement('section');
      aboutWindow.id = 'about-iphoto-window';
      aboutWindow.className = 'finder-window about-iphoto-window';
      aboutWindow.setAttribute('role', 'dialog');
      aboutWindow.setAttribute('aria-labelledby', 'about-iphoto-window-title');
      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(aboutWindow);
      });
      const title = document.createElement('div');
      title.id = 'about-iphoto-window-title';
      title.className = 'finder-title';
      title.textContent = 'About iPhoto';
      const content = document.createElement('div');
      content.className = 'finder-content about-finder-content';
      const heading = document.createElement('div');
      heading.className = 'about-finder-heading';
      heading.textContent = 'iPhoto';
      const copy = document.createElement('p');
      copy.className = 'about-finder-copy';
      copy.textContent = 'A simulated Mac OS X Tiger-style iPhoto library.';
      content.append(heading, copy);
      titleBar.append(closeButton, title);
      aboutWindow.append(titleBar, content);
      document.body.appendChild(aboutWindow);
      enableWindowFocus(aboutWindow);
      makeWindowDraggable(aboutWindow, titleBar);
    }

    function toggleIPhotoMenu(event) {
      event.stopPropagation();
      const shouldOpen = iPhotoDropdownMenu.hidden;
      closeAllMenuDropdowns();
      if (shouldOpen) {
        const bounds = iPhotoMenuButton.getBoundingClientRect();
        iPhotoDropdownMenu.style.left = `${Math.round(bounds.left)}px`;
        iPhotoDropdownMenu.style.top = `${Math.round(bounds.bottom)}px`;
        setMenuDropdownOpen(iPhotoMenuButton, iPhotoDropdownMenu, true);
      }
    }

    function toggleIPhotoFileMenu(event) {
      event.stopPropagation();
      const shouldOpen = iPhotoFileDropdownMenu.hidden;
      closeAllMenuDropdowns();
      if (shouldOpen) {
        const bounds = iPhotoFileMenuButton.getBoundingClientRect();
        iPhotoFileDropdownMenu.style.left = `${Math.round(bounds.left)}px`;
        iPhotoFileDropdownMenu.style.top = `${Math.round(bounds.bottom)}px`;
        setMenuDropdownOpen(iPhotoFileMenuButton, iPhotoFileDropdownMenu, true);
      }
    }

    function toggleIPhotoEditMenu(event) {
      event.stopPropagation();
      const shouldOpen = iPhotoEditDropdownMenu.hidden;
      closeAllMenuDropdowns();
      if (shouldOpen) {
        const bounds = iPhotoEditMenuButton.getBoundingClientRect();
        iPhotoEditDropdownMenu.style.left = `${Math.round(bounds.left)}px`;
        iPhotoEditDropdownMenu.style.top = `${Math.round(bounds.bottom)}px`;
        setMenuDropdownOpen(iPhotoEditMenuButton, iPhotoEditDropdownMenu, true);
      }
    }

    function toggleIPhotoPhotosMenu(event) {
      event.stopPropagation();
      const shouldOpen = iPhotoPhotosDropdownMenu.hidden;
      closeAllMenuDropdowns();
      if (shouldOpen) {
        const bounds = iPhotoPhotosMenuButton.getBoundingClientRect();
        iPhotoPhotosDropdownMenu.style.left = `${Math.round(bounds.left)}px`;
        iPhotoPhotosDropdownMenu.style.top = `${Math.round(bounds.bottom)}px`;
        setMenuDropdownOpen(iPhotoPhotosMenuButton, iPhotoPhotosDropdownMenu, true);
      }
    }

    function syncIPhotoDockContextMenuAvailability() {
      const iPhotoWindow = getIPhotoWindow();
      const iPhotoIsRunning = Boolean(iPhotoWindow && iPhotoWindow.isConnected);
      const iPhotoIsVisible = iPhotoIsRunning && !iPhotoWindow.classList.contains('is-minimized');
      setDockContextMenuItemAvailable(iPhotoDockShowAllWindowsMenuItem, iPhotoIsRunning);
      setDockContextMenuItemAvailable(iPhotoDockHideMenuItem, iPhotoIsVisible);
      setDockContextMenuItemAvailable(iPhotoDockQuitMenuItem, iPhotoIsRunning);
    }

    function openIPhotoDockContextMenu(event) {
      event.preventDefault();
      event.stopPropagation();
      closeAllMenuDropdowns();
      syncIPhotoDockContextMenuAvailability();
      positionDockContextMenu(iPhotoDockContextMenu, iPhotoDockItem);
      iPhotoDockContextMenu.hidden = false;
    }


    const simulatedIMovieLibraryClips = Object.freeze([
      Object.freeze({ id: 'imovie-clip-aqua', name: 'Aqua Afternoon', duration: 8, palette: 0, kind: 'Video' }),
      Object.freeze({ id: 'imovie-clip-tiger', name: 'Tiger Stripe', duration: 6, palette: 1, kind: 'Video' }),
      Object.freeze({ id: 'imovie-clip-dockside', name: 'Dockside', duration: 10, palette: 2, kind: 'Video' }),
      Object.freeze({ id: 'imovie-clip-spotlight', name: 'Spotlight', duration: 5, palette: 3, kind: 'Video' }),
      Object.freeze({ id: 'imovie-clip-safari', name: 'Safari Wind', duration: 7, palette: 4, kind: 'Video' }),
      Object.freeze({ id: 'imovie-clip-graphite', name: 'Graphite Sky', duration: 4, palette: 5, kind: 'Video' })
    ]);

    let iMovieCurrentFileSystemObject = null;
    let iMovieOpenSelectedFileSystemObject = null;
    let iMovieTimeline = [];
    let iMovieSelectedClipId = simulatedIMovieLibraryClips[0].id;
    let iMovieSelectedInstanceId = null;
    let iMovieClipboardItem = null;
    let iMovieUndoHistory = [];
    let iMoviePlaybackState = 'stopped';
    let iMovieElapsedSeconds = 0;
    let iMoviePlaybackTimer;
    let nextIMovieInstanceSequence = 1;

    function isIMovieDocument(fileSystemObject) {
      return Boolean(
        fileSystemObject &&
        fileSystemObject.type === 'file' &&
        typeof fileSystemObject.name === 'string' &&
        fileSystemObject.name.slice(-7) === '.imovie'
      );
    }

    function getIMovieIconMarkup() {
      return `
        <svg viewBox="0 0 72 72" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <rect x="12" y="46" width="48" height="14" rx="2" fill="#2a3036"/>
          <path d="M36 10l5.6 11.2 12.4 1.8-9 8.8 2.2 12.2L36 38.4 24.8 44l2.2-12.2-9-8.8 12.4-1.8z" fill="#f36b1c" stroke="#8a220c"/>
        </svg>
      `;
    }

    function getIMovieWindow() {
      return document.getElementById('imovie-window');
    }

    function getIMovieLibraryClip(clipId) {
      return simulatedIMovieLibraryClips.find((clip) => clip.id === clipId) || null;
    }

    function formatIMovieTime(totalSeconds) {
      const seconds = Math.max(0, Math.floor(Number(totalSeconds) || 0));
      const minutes = Math.floor(seconds / 60);
      const remainder = seconds - minutes * 60;
      return `${minutes}:${remainder < 10 ? '0' : ''}${remainder}`;
    }

    function stopIMoviePlaybackTimer() {
      if (iMoviePlaybackTimer) {
        clearInterval(iMoviePlaybackTimer);
        iMoviePlaybackTimer = undefined;
      }
    }

    function getIMovieTimelineTotal() {
      return iMovieTimeline.reduce((sum, item) => sum + item.duration, 0);
    }

    function getIMoviePlayingItem() {
      let remaining = iMovieElapsedSeconds;
      for (let index = 0; index < iMovieTimeline.length; index += 1) {
        const item = iMovieTimeline[index];
        if (remaining < item.duration) {
          return item;
        }
        remaining -= item.duration;
      }
      return iMovieTimeline[iMovieTimeline.length - 1] || null;
    }

    function cloneIMovieTimeline(timeline) {
      return timeline.map((item) => ({
        instanceId: item.instanceId,
        clipId: item.clipId,
        duration: item.duration
      }));
    }

    function snapshotIMovieProject() {
      return {
        timeline: cloneIMovieTimeline(iMovieTimeline),
        selectedClipId: iMovieSelectedClipId,
        selectedInstanceId: iMovieSelectedInstanceId
      };
    }

    function applyIMovieSnapshot(snapshot) {
      iMovieTimeline = cloneIMovieTimeline(snapshot.timeline);
      iMovieSelectedClipId = snapshot.selectedClipId;
      iMovieSelectedInstanceId = snapshot.selectedInstanceId;
    }

    function pushIMovieUndoSnapshot() {
      iMovieUndoHistory.push(snapshotIMovieProject());
      if (iMovieUndoHistory.length > 20) {
        iMovieUndoHistory.shift();
      }
    }

    function resetIMovieSessionState() {
      stopIMoviePlaybackTimer();
      iMovieCurrentFileSystemObject = null;
      iMovieOpenSelectedFileSystemObject = null;
      iMovieTimeline = [];
      iMovieSelectedClipId = simulatedIMovieLibraryClips[0].id;
      iMovieSelectedInstanceId = null;
      iMovieClipboardItem = null;
      iMovieUndoHistory = [];
      iMoviePlaybackState = 'stopped';
      iMovieElapsedSeconds = 0;
    }

    function createIMovieTimelineItem(clipId, duration) {
      const libraryClip = getIMovieLibraryClip(clipId);
      const item = {
        instanceId: `imovie-item-${nextIMovieInstanceSequence}`,
        clipId,
        duration: duration || (libraryClip ? libraryClip.duration : 4)
      };
      nextIMovieInstanceSequence += 1;
      return item;
    }

    function getIMovieClipMarkup(clip) {
      const palettes = [
        ['#4ec8f4', '#07589c'],
        ['#f4a04a', '#a4161a'],
        ['#d5dbe1', '#5d6974'],
        ['#ffe36a', '#3a2a08'],
        ['#6ec4f4', '#163a68'],
        ['#c8c8c8', '#4a4a4a']
      ];
      const palette = palettes[(clip ? clip.palette : 0) % palettes.length];
      const gradientId = `imovieArt${clip ? clip.id : 'empty'}`;
      return `
        <svg viewBox="0 0 160 90" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <defs>
            <linearGradient id="${gradientId}" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0" stop-color="${palette[0]}"/>
              <stop offset="1" stop-color="${palette[1]}"/>
            </linearGradient>
          </defs>
          <rect width="160" height="90" fill="url(#${gradientId})"/>
          <rect x="0" y="0" width="160" height="10" fill="#111"/>
          <rect x="0" y="80" width="160" height="10" fill="#111"/>
          <polygon points="68,30 108,45 68,60" fill="#fff" opacity="0.88"/>
        </svg>
      `;
    }

    function updateIMovieWindowTitle() {
      const iMovieWindow = getIMovieWindow();
      const title = iMovieWindow && iMovieWindow.querySelector('.finder-title');
      if (title) {
        title.textContent = iMovieCurrentFileSystemObject
          ? iMovieCurrentFileSystemObject.name
          : 'Untitled';
      }
    }

    function renderIMovieMonitor() {
      const screen = document.getElementById('imovie-monitor-screen');
      const caption = document.getElementById('imovie-monitor-caption');
      const playButton = document.getElementById('imovie-play-button');
      const iMovieWindow = getIMovieWindow();
      const playingItem = iMoviePlaybackState === 'playing'
        ? getIMoviePlayingItem()
        : (iMovieTimeline.find((item) => item.instanceId === iMovieSelectedInstanceId) || iMovieTimeline[0] || null);
      const clip = playingItem
        ? getIMovieLibraryClip(playingItem.clipId)
        : getIMovieLibraryClip(iMovieSelectedClipId);
      if (screen) {
        screen.innerHTML = getIMovieClipMarkup(clip);
      }
      if (caption) {
        const total = getIMovieTimelineTotal();
        caption.textContent = clip
          ? `${clip.name} · ${formatIMovieTime(iMovieElapsedSeconds)} / ${formatIMovieTime(total)}`
          : 'No clip selected';
      }
      if (playButton) {
        playButton.classList.toggle('is-active', iMoviePlaybackState === 'playing');
      }
      if (iMovieWindow) {
        iMovieWindow.setAttribute('data-imovie-playback', iMoviePlaybackState);
        if (playingItem) {
          iMovieWindow.setAttribute('data-imovie-playing-instance', playingItem.instanceId);
        } else {
          iMovieWindow.removeAttribute('data-imovie-playing-instance');
        }
      }
    }

    function renderIMovieLibraryPane() {
      const pane = document.getElementById('imovie-library-list');
      if (!pane) {
        return;
      }
      pane.replaceChildren();
      simulatedIMovieLibraryClips.forEach((clip) => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'imovie-clip';
        item.setAttribute('data-clip-id', clip.id);
        item.classList.toggle('is-selected', clip.id === iMovieSelectedClipId && !iMovieSelectedInstanceId);
        const name = document.createElement('div');
        name.textContent = clip.name;
        const meta = document.createElement('div');
        meta.className = 'imovie-clip-meta';
        meta.textContent = `${clip.kind} · ${formatIMovieTime(clip.duration)}`;
        item.append(name, meta);
        item.addEventListener('click', (event) => {
          event.stopPropagation();
          iMovieSelectedClipId = clip.id;
          iMovieSelectedInstanceId = null;
          renderIMovieProject();
        });
        item.addEventListener('dblclick', (event) => {
          event.stopPropagation();
          iMovieSelectedClipId = clip.id;
          addIMovieClipToTimeline(clip.id);
        });
        pane.appendChild(item);
      });
    }

    function renderIMovieClipBrowser() {
      const browser = document.getElementById('imovie-clip-browser');
      if (!browser) {
        return;
      }
      browser.replaceChildren();
      simulatedIMovieLibraryClips.forEach((clip) => {
        const card = document.createElement('button');
        card.type = 'button';
        card.className = 'imovie-clip-card';
        card.setAttribute('data-clip-id', clip.id);
        card.setAttribute('aria-label', clip.name);
        card.classList.toggle('is-selected', clip.id === iMovieSelectedClipId && !iMovieSelectedInstanceId);
        const art = document.createElement('div');
        art.className = 'imovie-clip-card-art';
        art.innerHTML = getIMovieClipMarkup(clip);
        const name = document.createElement('div');
        name.className = 'imovie-clip-card-name';
        name.textContent = clip.name;
        card.append(art, name);
        card.addEventListener('click', (event) => {
          event.stopPropagation();
          iMovieSelectedClipId = clip.id;
          iMovieSelectedInstanceId = null;
          renderIMovieProject();
        });
        card.addEventListener('dblclick', (event) => {
          event.stopPropagation();
          iMovieSelectedClipId = clip.id;
          addIMovieClipToTimeline(clip.id);
        });
        browser.appendChild(card);
      });
    }

    function renderIMovieTimeline() {
      const timeline = document.getElementById('imovie-timeline');
      if (!timeline) {
        return;
      }
      timeline.replaceChildren();
      if (iMovieTimeline.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'imovie-timeline-empty';
        empty.id = 'imovie-timeline-empty';
        empty.textContent = 'Drag or add clips to the timeline.';
        timeline.appendChild(empty);
        return;
      }
      const playingItem = iMoviePlaybackState === 'playing' ? getIMoviePlayingItem() : null;
      iMovieTimeline.forEach((item, itemIndex) => {
        const clip = getIMovieLibraryClip(item.clipId);
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'imovie-timeline-clip';
        button.setAttribute('data-instance-id', item.instanceId);
        button.setAttribute('data-clip-id', item.clipId);
        button.setAttribute('data-timeline-index', String(itemIndex));
        button.classList.toggle('is-selected', item.instanceId === iMovieSelectedInstanceId);
        button.classList.toggle('is-playing', Boolean(playingItem && playingItem.instanceId === item.instanceId));
        const name = document.createElement('div');
        name.textContent = clip ? clip.name : 'Clip';
        const meta = document.createElement('div');
        meta.textContent = formatIMovieTime(item.duration);
        button.append(name, meta);
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          iMovieSelectedInstanceId = item.instanceId;
          iMovieSelectedClipId = item.clipId;
          renderIMovieProject();
        });
        timeline.appendChild(button);
      });
    }

    function renderIMovieProject() {
      renderIMovieLibraryPane();
      renderIMovieClipBrowser();
      renderIMovieTimeline();
      renderIMovieMonitor();
      updateIMovieWindowTitle();
    }

    function addIMovieClipToTimeline(clipId) {
      const libraryClip = getIMovieLibraryClip(clipId || iMovieSelectedClipId);
      if (!libraryClip) {
        return;
      }
      pushIMovieUndoSnapshot();
      const item = createIMovieTimelineItem(libraryClip.id, libraryClip.duration);
      iMovieTimeline.push(item);
      iMovieSelectedInstanceId = item.instanceId;
      iMovieSelectedClipId = libraryClip.id;
      renderIMovieProject();
    }

    function getSelectedIMovieTimelineIndex() {
      return iMovieTimeline.findIndex((item) => item.instanceId === iMovieSelectedInstanceId);
    }

    function removeIMovieTimelineClip() {
      const index = getSelectedIMovieTimelineIndex();
      if (index < 0) {
        return;
      }
      pushIMovieUndoSnapshot();
      iMovieTimeline.splice(index, 1);
      const next = iMovieTimeline[Math.min(index, iMovieTimeline.length - 1)];
      iMovieSelectedInstanceId = next ? next.instanceId : null;
      renderIMovieProject();
    }

    function splitIMovieTimelineClip() {
      const index = getSelectedIMovieTimelineIndex();
      if (index < 0) {
        return;
      }
      const item = iMovieTimeline[index];
      if (item.duration < 2) {
        return;
      }
      pushIMovieUndoSnapshot();
      const leftDuration = Math.floor(item.duration / 2);
      const rightDuration = item.duration - leftDuration;
      item.duration = leftDuration;
      const rightItem = createIMovieTimelineItem(item.clipId, rightDuration);
      iMovieTimeline.splice(index + 1, 0, rightItem);
      iMovieSelectedInstanceId = item.instanceId;
      renderIMovieProject();
    }

    function trimIMovieTimelineClip() {
      const index = getSelectedIMovieTimelineIndex();
      if (index < 0) {
        return;
      }
      const item = iMovieTimeline[index];
      if (item.duration <= 1) {
        return;
      }
      pushIMovieUndoSnapshot();
      item.duration -= 1;
      renderIMovieProject();
    }

    function moveIMovieTimelineClip(offset) {
      const index = getSelectedIMovieTimelineIndex();
      const nextIndex = index + offset;
      if (index < 0 || nextIndex < 0 || nextIndex >= iMovieTimeline.length) {
        return;
      }
      pushIMovieUndoSnapshot();
      const [item] = iMovieTimeline.splice(index, 1);
      iMovieTimeline.splice(nextIndex, 0, item);
      iMovieSelectedInstanceId = item.instanceId;
      renderIMovieProject();
    }

    function tickIMoviePlayback() {
      if (iMoviePlaybackState !== 'playing') {
        return;
      }
      const total = getIMovieTimelineTotal();
      if (total <= 0) {
        stopIMoviePlayback();
        return;
      }
      iMovieElapsedSeconds += 1;
      if (iMovieElapsedSeconds >= total) {
        stopIMoviePlayback();
        return;
      }
      renderIMovieMonitor();
      renderIMovieTimeline();
    }

    function playIMoviePreview() {
      if (iMovieTimeline.length === 0) {
        return;
      }
      if (iMoviePlaybackState === 'playing') {
        return;
      }
      iMoviePlaybackState = 'playing';
      if (iMovieElapsedSeconds >= getIMovieTimelineTotal()) {
        iMovieElapsedSeconds = 0;
      }
      stopIMoviePlaybackTimer();
      iMoviePlaybackTimer = setInterval(tickIMoviePlayback, 1000);
      renderIMovieProject();
    }

    function stopIMoviePlayback() {
      stopIMoviePlaybackTimer();
      iMoviePlaybackState = 'stopped';
      iMovieElapsedSeconds = 0;
      renderIMovieProject();
    }

    function undoIMovieProject() {
      const snapshot = iMovieUndoHistory.pop();
      if (!snapshot) {
        return;
      }
      stopIMoviePlayback();
      applyIMovieSnapshot(snapshot);
      renderIMovieProject();
    }

    function copyIMovieSelection() {
      const index = getSelectedIMovieTimelineIndex();
      if (index < 0) {
        const clip = getIMovieLibraryClip(iMovieSelectedClipId);
        if (clip) {
          simulatedClipboard.text = clip.name;
        }
        return;
      }
      const item = iMovieTimeline[index];
      iMovieClipboardItem = {
        clipId: item.clipId,
        duration: item.duration
      };
      const clip = getIMovieLibraryClip(item.clipId);
      simulatedClipboard.text = clip ? clip.name : '';
    }

    function cutIMovieSelection() {
      copyIMovieSelection();
      removeIMovieTimelineClip();
    }

    function pasteIMovieSelection() {
      if (!iMovieClipboardItem) {
        return;
      }
      pushIMovieUndoSnapshot();
      const item = createIMovieTimelineItem(iMovieClipboardItem.clipId, iMovieClipboardItem.duration);
      iMovieTimeline.push(item);
      iMovieSelectedInstanceId = item.instanceId;
      iMovieSelectedClipId = item.clipId;
      renderIMovieProject();
    }

    function selectAllIMovieTimeline() {
      if (iMovieTimeline.length === 0) {
        return;
      }
      iMovieSelectedInstanceId = iMovieTimeline[0].instanceId;
      iMovieSelectedClipId = iMovieTimeline[0].clipId;
      renderIMovieProject();
    }

    function startNewIMovieProject() {
      resetIMovieSessionState();
      renderIMovieProject();
    }

    function loadIMovieProject(fileSystemObject) {
      iMovieCurrentFileSystemObject = fileSystemObject || null;
      const stored = fileSystemObject
        ? simulatedIMovieProjects.get(fileSystemObject)
        : null;
      stopIMoviePlaybackTimer();
      iMoviePlaybackState = 'stopped';
      iMovieElapsedSeconds = 0;
      if (stored && Array.isArray(stored.timeline)) {
        iMovieTimeline = cloneIMovieTimeline(stored.timeline);
        iMovieSelectedInstanceId = stored.selectedInstanceId || (iMovieTimeline[0] ? iMovieTimeline[0].instanceId : null);
        iMovieSelectedClipId = stored.selectedClipId || (iMovieTimeline[0] ? iMovieTimeline[0].clipId : simulatedIMovieLibraryClips[0].id);
      } else {
        iMovieTimeline = [];
        iMovieSelectedInstanceId = null;
        iMovieSelectedClipId = simulatedIMovieLibraryClips[0].id;
      }
      iMovieUndoHistory = [];
      renderIMovieProject();
      if (fileSystemObject) {
        recordSimulatedRecentItem(fileSystemObject);
      }
    }

    function getIMovieProjectPayload() {
      return Object.freeze({
        selectedClipId: iMovieSelectedClipId,
        selectedInstanceId: iMovieSelectedInstanceId,
        timeline: Object.freeze(cloneIMovieTimeline(iMovieTimeline).map((item) => Object.freeze(item)))
      });
    }

    function getIMovieProjectPlainLength(payload) {
      return payload.timeline.reduce((sum, item) => sum + String(item.clipId).length + item.duration, 0);
    }

    function normalizeIMovieDocumentName(desiredName) {
      let name = typeof desiredName === 'string' ? desiredName : '';
      name = name.split('/').join('').split('\\').join('').trim();
      if (!name) {
        name = 'Untitled';
      }
      if (name.slice(-7) !== '.imovie') {
        name += '.imovie';
      }
      return name;
    }

    function getAvailableIMovieDocumentName(parentFileSystemObject, desiredName) {
      const existingNames = new Set(
        getFileSystemObjectChildren(parentFileSystemObject).map((child) => child.name)
      );
      const baseName = normalizeIMovieDocumentName(desiredName);
      if (!existingNames.has(baseName)) {
        return baseName;
      }
      const withoutSuffix = baseName.slice(0, -7);
      let nextNumber = 2;
      while (existingNames.has(`${withoutSuffix} ${nextNumber}.imovie`)) {
        nextNumber += 1;
      }
      return `${withoutSuffix} ${nextNumber}.imovie`;
    }

    function createIMovieDocumentFileSystemObject(documentName, plainTextLength) {
      return Object.freeze({
        name: documentName,
        type: 'file',
        createdAt: takeSimulatedModificationTimestamp(),
        modifiedAt: takeSimulatedModificationTimestamp(),
        size: plainTextLength || 1,
        label: simulatedNoLabel
      });
    }

    function saveIMovieProjectToFileSystemObject(fileSystemObject) {
      if (!fileSystemObject) {
        return;
      }
      const payload = getIMovieProjectPayload();
      simulatedIMovieProjects.set(fileSystemObject, payload);
      iMovieCurrentFileSystemObject = fileSystemObject;
      updateIMovieWindowTitle();
      recordSimulatedRecentItem(fileSystemObject);
      refreshOpenFinderWindows();
    }

    function saveIMovieProject() {
      if (iMovieCurrentFileSystemObject) {
        saveIMovieProjectToFileSystemObject(iMovieCurrentFileSystemObject);
        return;
      }
      const payload = getIMovieProjectPayload();
      const newFileSystemObject = createIMovieDocumentFileSystemObject(
        getAvailableIMovieDocumentName(documentsFileSystemObject, 'Untitled.imovie'),
        getIMovieProjectPlainLength(payload)
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      saveIMovieProjectToFileSystemObject(newFileSystemObject);
    }

    function saveIMovieProjectAs(desiredName) {
      const payload = getIMovieProjectPayload();
      const documentName = getAvailableIMovieDocumentName(
        documentsFileSystemObject,
        desiredName
      );
      if (
        iMovieCurrentFileSystemObject &&
        iMovieCurrentFileSystemObject.name === documentName
      ) {
        saveIMovieProjectToFileSystemObject(iMovieCurrentFileSystemObject);
        return;
      }
      const newFileSystemObject = createIMovieDocumentFileSystemObject(
        documentName,
        getIMovieProjectPlainLength(payload)
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      saveIMovieProjectToFileSystemObject(newFileSystemObject);
    }

    function showIMovieWindow(fileSystemObject) {
      recordSimulatedRecentItem(iMovieApplicationIdentity);
      const existingIMovieWindow = getIMovieWindow();
      if (existingIMovieWindow && existingIMovieWindow.isConnected) {
        if (fileSystemObject) {
          loadIMovieProject(fileSystemObject);
        }
        focusFinderWindow(existingIMovieWindow);
        return;
      }

      const iMovieWindow = document.createElement('section');
      iMovieWindow.id = 'imovie-window';
      iMovieWindow.className = 'finder-window imovie-window';
      iMovieWindow.setAttribute('role', 'dialog');
      iMovieWindow.setAttribute('aria-labelledby', 'imovie-window-title');
      iMovieWindow.setAttribute('data-imovie-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(iMovieWindow);
      });
      const title = document.createElement('div');
      title.id = 'imovie-window-title';
      title.className = 'finder-title';
      title.textContent = 'Untitled';
      titleBar.append(closeButton, title);

      const toolbar = document.createElement('div');
      toolbar.className = 'imovie-toolbar';
      function createIMovieToolButton(id, label, ariaLabel, action) {
        const button = document.createElement('button');
        button.type = 'button';
        button.id = id;
        button.className = 'imovie-tool-button';
        button.textContent = label;
        button.setAttribute('aria-label', ariaLabel);
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          action();
        });
        return button;
      }
      toolbar.append(
        createIMovieToolButton('imovie-play-button', 'Play', 'Play', playIMoviePreview),
        createIMovieToolButton('imovie-stop-button', 'Stop', 'Stop', stopIMoviePlayback),
        createIMovieToolButton('imovie-add-button', 'Add', 'Add Clip', () => {
          addIMovieClipToTimeline(iMovieSelectedClipId);
        }),
        createIMovieToolButton('imovie-split-button', 'Split', 'Split Clip', splitIMovieTimelineClip),
        createIMovieToolButton('imovie-trim-button', 'Trim', 'Trim Clip', trimIMovieTimelineClip)
      );

      const body = document.createElement('div');
      body.className = 'imovie-body';
      const top = document.createElement('div');
      top.className = 'imovie-top';
      const library = document.createElement('div');
      library.className = 'imovie-library';
      const libraryHeading = document.createElement('div');
      libraryHeading.className = 'imovie-library-heading';
      libraryHeading.textContent = 'CLIPS';
      const libraryList = document.createElement('div');
      libraryList.id = 'imovie-library-list';
      library.append(libraryHeading, libraryList);
      const monitor = document.createElement('div');
      monitor.className = 'imovie-monitor';
      const screen = document.createElement('div');
      screen.className = 'imovie-monitor-screen';
      screen.id = 'imovie-monitor-screen';
      const caption = document.createElement('div');
      caption.className = 'imovie-monitor-caption';
      caption.id = 'imovie-monitor-caption';
      monitor.append(screen, caption);
      top.append(library, monitor);
      const clips = document.createElement('div');
      clips.className = 'imovie-clips';
      clips.id = 'imovie-clip-browser';
      const timeline = document.createElement('div');
      timeline.className = 'imovie-timeline';
      timeline.id = 'imovie-timeline';
      body.append(top, clips, timeline);

      iMovieWindow.append(titleBar, toolbar, body);
      document.body.appendChild(iMovieWindow);
      enableWindowFocus(iMovieWindow);
      makeWindowDraggable(iMovieWindow, titleBar);
      if (fileSystemObject) {
        loadIMovieProject(fileSystemObject);
      } else {
        startNewIMovieProject();
      }
    }

