    const simulatedGarageBandInstruments = Object.freeze([
      Object.freeze({ id: 'gb-inst-piano', name: 'Grand Piano', color: '#d4a017' }),
      Object.freeze({ id: 'gb-inst-eguitar', name: 'Electric Guitar', color: '#c45c26' }),
      Object.freeze({ id: 'gb-inst-aguitar', name: 'Acoustic Guitar', color: '#b0894a' }),
      Object.freeze({ id: 'gb-inst-drums', name: 'Drum Kit', color: '#5a7d9a' }),
      Object.freeze({ id: 'gb-inst-bass', name: 'Electric Bass', color: '#3d6b4f' }),
      Object.freeze({ id: 'gb-inst-strings', name: 'Strings', color: '#8a5a9a' }),
      Object.freeze({ id: 'gb-inst-synth', name: 'Synth Pad', color: '#2f6f8a' }),
      Object.freeze({ id: 'gb-inst-horns', name: 'Horns', color: '#a43c3c' })
    ]);

    const simulatedGarageBandLoops = Object.freeze([
      Object.freeze({ id: 'gb-loop-piano-riff', name: 'Piano Riff', instrumentId: 'gb-inst-piano', duration: 4 }),
      Object.freeze({ id: 'gb-loop-acoustic-strum', name: 'Acoustic Strum', instrumentId: 'gb-inst-aguitar', duration: 4 }),
      Object.freeze({ id: 'gb-loop-electric-crunch', name: 'Electric Crunch', instrumentId: 'gb-inst-eguitar', duration: 3 }),
      Object.freeze({ id: 'gb-loop-garage-beat', name: 'Garage Beat', instrumentId: 'gb-inst-drums', duration: 4 }),
      Object.freeze({ id: 'gb-loop-shaker', name: 'Shaker Groove', instrumentId: 'gb-inst-drums', duration: 2 }),
      Object.freeze({ id: 'gb-loop-walking-bass', name: 'Walking Bass', instrumentId: 'gb-inst-bass', duration: 4 }),
      Object.freeze({ id: 'gb-loop-soft-pad', name: 'Soft Pad', instrumentId: 'gb-inst-synth', duration: 8 }),
      Object.freeze({ id: 'gb-loop-horn-stabs', name: 'Horn Stabs', instrumentId: 'gb-inst-horns', duration: 2 })
    ]);

    const garageBandTimelineLength = 16;
    let garageBandCurrentFileSystemObject = null;
    let garageBandOpenSelectedFileSystemObject = null;
    let garageBandTracks = [];
    let garageBandSelectedTrackId = null;
    let garageBandSelectedClipInstanceId = null;
    let garageBandSelectedInstrumentId = simulatedGarageBandInstruments[0].id;
    let garageBandSelectedLoopId = simulatedGarageBandLoops[0].id;
    let garageBandClipboardClip = null;
    let garageBandUndoHistory = [];
    let garageBandPlaybackState = 'stopped';
    let garageBandPlayheadPosition = 0;
    let garageBandPlaybackTimer;
    let nextGarageBandTrackSequence = 1;
    let nextGarageBandClipSequence = 1;

    function isGarageBandDocument(fileSystemObject) {
      return Boolean(
        fileSystemObject &&
        fileSystemObject.type === 'file' &&
        typeof fileSystemObject.name === 'string' &&
        fileSystemObject.name.slice(-5) === '.band'
      );
    }

    function getGarageBandIconMarkup() {
      return `
        <svg viewBox="0 0 72 72" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <ellipse cx="28" cy="44" rx="18" ry="14" fill="#d8891c" stroke="#8a4a10"/>
          <ellipse cx="28" cy="44" rx="6" ry="5" fill="#2a1c10"/>
          <rect x="42" y="40" width="18" height="6" rx="2" fill="#c9a056" stroke="#8a4a10"/>
          <rect x="58" y="38" width="7" height="10" rx="1.5" fill="#a56b2a"/>
        </svg>
      `;
    }

    function getGarageBandWindow() {
      return document.getElementById('garageband-window');
    }

    function getGarageBandInstrument(instrumentId) {
      return simulatedGarageBandInstruments.find((instrument) => instrument.id === instrumentId) || simulatedGarageBandInstruments[0];
    }

    function getGarageBandLoop(loopId) {
      return simulatedGarageBandLoops.find((loop) => loop.id === loopId) || null;
    }

    function formatGarageBandTime(totalBeats) {
      const beats = Math.max(0, Math.floor(Number(totalBeats) || 0));
      const measures = Math.floor(beats / 4);
      const remainder = beats - measures * 4;
      return `${measures}:${remainder}`;
    }

    function stopGarageBandPlaybackTimer() {
      if (garageBandPlaybackTimer) {
        clearInterval(garageBandPlaybackTimer);
        garageBandPlaybackTimer = undefined;
      }
    }

    function cloneGarageBandClip(clip) {
      return {
        instanceId: clip.instanceId,
        loopId: clip.loopId,
        position: clip.position,
        duration: clip.duration
      };
    }

    function cloneGarageBandTrack(track) {
      return {
        id: track.id,
        name: track.name,
        instrumentId: track.instrumentId,
        volume: track.volume,
        muted: track.muted,
        solo: track.solo,
        clips: track.clips.map(cloneGarageBandClip)
      };
    }

    function cloneGarageBandTracks(tracks) {
      return tracks.map(cloneGarageBandTrack);
    }

    function snapshotGarageBandProject() {
      return {
        tracks: cloneGarageBandTracks(garageBandTracks),
        selectedTrackId: garageBandSelectedTrackId,
        selectedClipInstanceId: garageBandSelectedClipInstanceId,
        selectedInstrumentId: garageBandSelectedInstrumentId,
        selectedLoopId: garageBandSelectedLoopId
      };
    }

    function applyGarageBandSnapshot(snapshot) {
      garageBandTracks = cloneGarageBandTracks(snapshot.tracks);
      garageBandSelectedTrackId = snapshot.selectedTrackId;
      garageBandSelectedClipInstanceId = snapshot.selectedClipInstanceId;
      garageBandSelectedInstrumentId = snapshot.selectedInstrumentId || simulatedGarageBandInstruments[0].id;
      garageBandSelectedLoopId = snapshot.selectedLoopId || simulatedGarageBandLoops[0].id;
    }

    function pushGarageBandUndoSnapshot() {
      garageBandUndoHistory.push(snapshotGarageBandProject());
      if (garageBandUndoHistory.length > 20) {
        garageBandUndoHistory.shift();
      }
    }

    function resetGarageBandSessionState() {
      stopGarageBandPlaybackTimer();
      garageBandCurrentFileSystemObject = null;
      garageBandOpenSelectedFileSystemObject = null;
      garageBandTracks = [];
      garageBandSelectedTrackId = null;
      garageBandSelectedClipInstanceId = null;
      garageBandSelectedInstrumentId = simulatedGarageBandInstruments[0].id;
      garageBandSelectedLoopId = simulatedGarageBandLoops[0].id;
      garageBandClipboardClip = null;
      garageBandUndoHistory = [];
      garageBandPlaybackState = 'stopped';
      garageBandPlayheadPosition = 0;
    }

    function createGarageBandClip(loopId, position, duration) {
      const loop = getGarageBandLoop(loopId);
      const clip = {
        instanceId: `gb-clip-${nextGarageBandClipSequence}`,
        loopId,
        position: Math.max(0, position || 0),
        duration: duration || (loop ? loop.duration : 4)
      };
      nextGarageBandClipSequence += 1;
      return clip;
    }

    function getAvailableGarageBandTrackName() {
      const existingNames = new Set(garageBandTracks.map((track) => track.name));
      let nextNumber = 1;
      while (existingNames.has(`Track ${nextNumber}`)) {
        nextNumber += 1;
      }
      return `Track ${nextNumber}`;
    }

    function createGarageBandTrack(name, instrumentId) {
      const instrument = getGarageBandInstrument(instrumentId);
      const track = {
        id: `gb-track-${nextGarageBandTrackSequence}`,
        name: name || getAvailableGarageBandTrackName(),
        instrumentId: instrument.id,
        volume: 80,
        muted: false,
        solo: false,
        clips: []
      };
      nextGarageBandTrackSequence += 1;
      return track;
    }

    function getSelectedGarageBandTrack() {
      return garageBandTracks.find((track) => track.id === garageBandSelectedTrackId) || null;
    }

    function getSelectedGarageBandClip() {
      for (let trackIndex = 0; trackIndex < garageBandTracks.length; trackIndex += 1) {
        const track = garageBandTracks[trackIndex];
        const clip = track.clips.find((item) => item.instanceId === garageBandSelectedClipInstanceId);
        if (clip) {
          return { track, clip };
        }
      }
      return null;
    }

    function getGarageBandTrackEnd(track) {
      return track.clips.reduce((end, clip) => Math.max(end, clip.position + clip.duration), 0);
    }

    function updateGarageBandWindowTitle() {
      const garageBandWindow = getGarageBandWindow();
      const title = garageBandWindow && garageBandWindow.querySelector('.finder-title');
      if (title) {
        title.textContent = garageBandCurrentFileSystemObject
          ? garageBandCurrentFileSystemObject.name
          : 'Untitled';
      }
    }

    function renderGarageBandPlayhead() {
      const playhead = document.getElementById('garageband-playhead');
      const garageBandWindow = getGarageBandWindow();
      const playButton = document.getElementById('garageband-play-button');
      const status = document.getElementById('garageband-status');
      if (playhead) {
        playhead.style.left = `${(garageBandPlayheadPosition / garageBandTimelineLength) * 100}%`;
      }
      if (playButton) {
        playButton.classList.toggle('is-active', garageBandPlaybackState === 'playing');
      }
      if (garageBandWindow) {
        garageBandWindow.setAttribute('data-garageband-playback', garageBandPlaybackState);
        garageBandWindow.setAttribute('data-garageband-playhead', String(garageBandPlayheadPosition));
      }
      if (status) {
        const selectedTrack = getSelectedGarageBandTrack();
        const instrument = selectedTrack ? getGarageBandInstrument(selectedTrack.instrumentId) : null;
        status.textContent = `${garageBandTracks.length} tracks · Playhead ${formatGarageBandTime(garageBandPlayheadPosition)} · ${instrument ? instrument.name : 'No track'}`;
      }
    }

    function renderGarageBandTrackList() {
      const pane = document.getElementById('garageband-track-list');
      if (!pane) {
        return;
      }
      pane.replaceChildren();
      const heading = document.createElement('div');
      heading.className = 'garageband-track-heading';
      heading.textContent = 'TRACKS';
      pane.appendChild(heading);
      const anySolo = garageBandTracks.some((track) => track.solo);
      garageBandTracks.forEach((track) => {
        const instrument = getGarageBandInstrument(track.instrumentId);
        const item = document.createElement('div');
        item.className = 'garageband-track';
        item.setAttribute('data-track-id', track.id);
        item.setAttribute('data-instrument-id', track.instrumentId);
        item.setAttribute('data-volume', String(track.volume));
        item.setAttribute('data-muted', String(track.muted));
        item.setAttribute('data-solo', String(track.solo));
        item.setAttribute('aria-label', track.name);
        item.classList.toggle('is-selected', track.id === garageBandSelectedTrackId);
        item.classList.toggle('is-muted', track.muted);
        item.classList.toggle('is-solo', track.solo);
        if (anySolo && !track.solo) {
          item.classList.add('is-muted');
        }
        const name = document.createElement('div');
        name.className = 'garageband-track-name';
        name.textContent = track.name;
        const instrumentLabel = document.createElement('div');
        instrumentLabel.className = 'garageband-track-instrument';
        instrumentLabel.textContent = instrument.name;
        const controls = document.createElement('div');
        controls.className = 'garageband-track-controls';
        const muteButton = document.createElement('button');
        muteButton.type = 'button';
        muteButton.className = 'garageband-track-toggle';
        muteButton.textContent = 'M';
        muteButton.setAttribute('aria-label', `Mute ${track.name}`);
        muteButton.setAttribute('aria-pressed', String(track.muted));
        muteButton.classList.toggle('is-active', track.muted);
        muteButton.addEventListener('click', (event) => {
          event.stopPropagation();
          toggleGarageBandTrackMute(track.id);
        });
        const soloButton = document.createElement('button');
        soloButton.type = 'button';
        soloButton.className = 'garageband-track-toggle';
        soloButton.textContent = 'S';
        soloButton.setAttribute('aria-label', `Solo ${track.name}`);
        soloButton.setAttribute('aria-pressed', String(track.solo));
        soloButton.classList.toggle('is-solo-active', track.solo);
        soloButton.addEventListener('click', (event) => {
          event.stopPropagation();
          toggleGarageBandTrackSolo(track.id);
        });
        const volume = document.createElement('input');
        volume.type = 'range';
        volume.className = 'garageband-volume';
        volume.min = '0';
        volume.max = '100';
        volume.value = String(track.volume);
        volume.setAttribute('aria-label', `${track.name} volume`);
        volume.addEventListener('click', (event) => {
          event.stopPropagation();
        });
        volume.addEventListener('pointerdown', (event) => {
          event.stopPropagation();
        });
        volume.addEventListener('input', (event) => {
          event.stopPropagation();
        });
        volume.addEventListener('change', (event) => {
          event.stopPropagation();
          setGarageBandTrackVolume(track.id, Number(volume.value) || 0);
        });
        controls.append(muteButton, soloButton, volume);
        item.append(name, instrumentLabel, controls);
        item.addEventListener('click', (event) => {
          event.stopPropagation();
          garageBandSelectedTrackId = track.id;
          garageBandSelectedClipInstanceId = null;
          garageBandSelectedInstrumentId = track.instrumentId;
          renderGarageBandProject();
        });
        pane.appendChild(item);
      });
    }

    function renderGarageBandTimeline() {
      const timeline = document.getElementById('garageband-timeline');
      if (!timeline) {
        return;
      }
      timeline.replaceChildren();
      garageBandTracks.forEach((track) => {
        const instrument = getGarageBandInstrument(track.instrumentId);
        const row = document.createElement('div');
        row.className = 'garageband-timeline-row';
        row.setAttribute('data-track-id', track.id);
        track.clips.forEach((clip) => {
          const loop = getGarageBandLoop(clip.loopId);
          const button = document.createElement('button');
          button.type = 'button';
          button.className = 'garageband-clip';
          button.setAttribute('data-instance-id', clip.instanceId);
          button.setAttribute('data-track-id', track.id);
          button.setAttribute('data-loop-id', clip.loopId);
          button.setAttribute('data-clip-position', String(clip.position));
          button.style.left = `${(clip.position / garageBandTimelineLength) * 100}%`;
          button.style.width = `${(clip.duration / garageBandTimelineLength) * 100}%`;
          button.style.background = `linear-gradient(${instrument.color}, #2a1c10)`;
          button.classList.toggle('is-selected', clip.instanceId === garageBandSelectedClipInstanceId);
          const label = document.createElement('div');
          label.textContent = loop ? loop.name : 'Loop';
          button.appendChild(label);
          button.addEventListener('click', (event) => {
            event.stopPropagation();
            garageBandSelectedTrackId = track.id;
            garageBandSelectedClipInstanceId = clip.instanceId;
            garageBandSelectedLoopId = clip.loopId;
            renderGarageBandProject();
          });
          row.appendChild(button);
        });
        timeline.appendChild(row);
      });
      const playhead = document.createElement('div');
      playhead.className = 'garageband-playhead';
      playhead.id = 'garageband-playhead';
      timeline.appendChild(playhead);
    }

    function renderGarageBandBrowser() {
      const instrumentList = document.getElementById('garageband-instrument-list');
      const loopList = document.getElementById('garageband-loop-list');
      if (instrumentList) {
        instrumentList.replaceChildren();
        simulatedGarageBandInstruments.forEach((instrument) => {
          const item = document.createElement('button');
          item.type = 'button';
          item.className = 'garageband-browser-item';
          item.setAttribute('data-instrument-id', instrument.id);
          item.classList.toggle('is-selected', instrument.id === garageBandSelectedInstrumentId);
          item.textContent = instrument.name;
          item.addEventListener('click', (event) => {
            event.stopPropagation();
            setGarageBandSelectedInstrument(instrument.id);
          });
          instrumentList.appendChild(item);
        });
      }
      if (loopList) {
        loopList.replaceChildren();
        simulatedGarageBandLoops.forEach((loop) => {
          const item = document.createElement('button');
          item.type = 'button';
          item.className = 'garageband-browser-item';
          item.setAttribute('data-loop-id', loop.id);
          item.classList.toggle('is-selected', loop.id === garageBandSelectedLoopId);
          const name = document.createElement('div');
          name.textContent = loop.name;
          const meta = document.createElement('div');
          meta.className = 'garageband-browser-meta';
          meta.textContent = `${getGarageBandInstrument(loop.instrumentId).name} · ${formatGarageBandTime(loop.duration)}`;
          item.append(name, meta);
          item.addEventListener('click', (event) => {
            event.stopPropagation();
            garageBandSelectedLoopId = loop.id;
            renderGarageBandProject();
          });
          item.addEventListener('dblclick', (event) => {
            event.stopPropagation();
            garageBandSelectedLoopId = loop.id;
            addGarageBandLoop(loop.id);
          });
          loopList.appendChild(item);
        });
      }
    }

    function renderGarageBandProject() {
      renderGarageBandTrackList();
      renderGarageBandTimeline();
      renderGarageBandBrowser();
      renderGarageBandPlayhead();
      updateGarageBandWindowTitle();
    }

    function getDefaultGarageBandTracks() {
      const piano = createGarageBandTrack('Grand Piano', 'gb-inst-piano');
      piano.clips.push(createGarageBandClip('gb-loop-piano-riff', 0, 4));
      const drums = createGarageBandTrack('Drum Kit', 'gb-inst-drums');
      drums.clips.push(createGarageBandClip('gb-loop-garage-beat', 0, 4));
      const bass = createGarageBandTrack('Electric Bass', 'gb-inst-bass');
      bass.clips.push(createGarageBandClip('gb-loop-walking-bass', 0, 4));
      return [piano, drums, bass];
    }

    function startNewGarageBandProject() {
      resetGarageBandSessionState();
      garageBandTracks = getDefaultGarageBandTracks();
      garageBandSelectedTrackId = garageBandTracks[0].id;
      garageBandSelectedInstrumentId = garageBandTracks[0].instrumentId;
      renderGarageBandProject();
    }

    function addGarageBandTrack() {
      pushGarageBandUndoSnapshot();
      const track = createGarageBandTrack();
      garageBandTracks.push(track);
      garageBandSelectedTrackId = track.id;
      garageBandSelectedClipInstanceId = null;
      garageBandSelectedInstrumentId = track.instrumentId;
      renderGarageBandProject();
    }

    function duplicateGarageBandTrack() {
      const track = getSelectedGarageBandTrack();
      if (!track) {
        return;
      }
      pushGarageBandUndoSnapshot();
      const duplicate = createGarageBandTrack(`${track.name} Copy`, track.instrumentId);
      duplicate.volume = track.volume;
      duplicate.muted = track.muted;
      duplicate.solo = track.solo;
      duplicate.clips = track.clips.map((clip) => createGarageBandClip(clip.loopId, clip.position, clip.duration));
      const index = garageBandTracks.findIndex((item) => item.id === track.id);
      garageBandTracks.splice(index + 1, 0, duplicate);
      garageBandSelectedTrackId = duplicate.id;
      garageBandSelectedClipInstanceId = duplicate.clips[0] ? duplicate.clips[0].instanceId : null;
      renderGarageBandProject();
    }

    function removeGarageBandTrack() {
      const index = garageBandTracks.findIndex((track) => track.id === garageBandSelectedTrackId);
      if (index < 0) {
        return;
      }
      pushGarageBandUndoSnapshot();
      garageBandTracks.splice(index, 1);
      const next = garageBandTracks[Math.min(index, garageBandTracks.length - 1)];
      garageBandSelectedTrackId = next ? next.id : null;
      garageBandSelectedClipInstanceId = null;
      renderGarageBandProject();
    }

    function setGarageBandSelectedInstrument(instrumentId) {
      garageBandSelectedInstrumentId = instrumentId;
      const track = getSelectedGarageBandTrack();
      if (track && track.instrumentId !== instrumentId) {
        pushGarageBandUndoSnapshot();
        track.instrumentId = instrumentId;
      }
      renderGarageBandProject();
    }

    function addGarageBandLoop(loopId) {
      const loop = getGarageBandLoop(loopId || garageBandSelectedLoopId);
      if (!loop) {
        return;
      }
      pushGarageBandUndoSnapshot();
      let track = getSelectedGarageBandTrack();
      if (!track) {
        track = createGarageBandTrack();
        garageBandTracks.push(track);
      }
      garageBandSelectedLoopId = loop.id;
      const clip = createGarageBandClip(loop.id, getGarageBandTrackEnd(track), loop.duration);
      track.clips.push(clip);
      garageBandSelectedClipInstanceId = clip.instanceId;
      garageBandSelectedTrackId = track.id;
      renderGarageBandProject();
    }

    function removeGarageBandClip() {
      const selected = getSelectedGarageBandClip();
      if (!selected) {
        return;
      }
      pushGarageBandUndoSnapshot();
      selected.track.clips = selected.track.clips.filter((clip) => clip.instanceId !== selected.clip.instanceId);
      garageBandSelectedClipInstanceId = selected.track.clips[0] ? selected.track.clips[0].instanceId : null;
      renderGarageBandProject();
    }

    function duplicateGarageBandClip() {
      const selected = getSelectedGarageBandClip();
      if (!selected) {
        return;
      }
      pushGarageBandUndoSnapshot();
      const duplicate = createGarageBandClip(
        selected.clip.loopId,
        selected.clip.position + selected.clip.duration,
        selected.clip.duration
      );
      selected.track.clips.push(duplicate);
      garageBandSelectedClipInstanceId = duplicate.instanceId;
      renderGarageBandProject();
    }

    function moveGarageBandClip(offset) {
      const selected = getSelectedGarageBandClip();
      if (!selected) {
        return;
      }
      const nextPosition = selected.clip.position + offset;
      if (nextPosition < 0) {
        return;
      }
      pushGarageBandUndoSnapshot();
      selected.clip.position = nextPosition;
      renderGarageBandProject();
    }

    function setGarageBandTrackVolume(trackId, volume) {
      const track = garageBandTracks.find((item) => item.id === trackId);
      if (!track) {
        return;
      }
      const nextVolume = Math.max(0, Math.min(100, Math.round(volume)));
      if (track.volume === nextVolume) {
        return;
      }
      pushGarageBandUndoSnapshot();
      track.volume = nextVolume;
      renderGarageBandProject();
    }

    function toggleGarageBandTrackMute(trackId) {
      const track = garageBandTracks.find((item) => item.id === trackId);
      if (!track) {
        return;
      }
      pushGarageBandUndoSnapshot();
      track.muted = !track.muted;
      garageBandSelectedTrackId = track.id;
      renderGarageBandProject();
    }

    function toggleGarageBandTrackSolo(trackId) {
      const track = garageBandTracks.find((item) => item.id === trackId);
      if (!track) {
        return;
      }
      pushGarageBandUndoSnapshot();
      track.solo = !track.solo;
      garageBandSelectedTrackId = track.id;
      renderGarageBandProject();
    }

    function tickGarageBandPlayback() {
      if (garageBandPlaybackState !== 'playing') {
        return;
      }
      garageBandPlayheadPosition += 1;
      if (garageBandPlayheadPosition >= garageBandTimelineLength) {
        stopGarageBandPlayback();
        return;
      }
      renderGarageBandPlayhead();
    }

    function playGarageBandPreview() {
      if (garageBandPlaybackState === 'playing') {
        return;
      }
      garageBandPlaybackState = 'playing';
      if (garageBandPlayheadPosition >= garageBandTimelineLength) {
        garageBandPlayheadPosition = 0;
      }
      stopGarageBandPlaybackTimer();
      garageBandPlaybackTimer = setInterval(tickGarageBandPlayback, 1000);
      renderGarageBandPlayhead();
    }

    function stopGarageBandPlayback() {
      stopGarageBandPlaybackTimer();
      garageBandPlaybackState = 'stopped';
      garageBandPlayheadPosition = 0;
      renderGarageBandPlayhead();
    }

    function undoGarageBandProject() {
      const snapshot = garageBandUndoHistory.pop();
      if (!snapshot) {
        return;
      }
      stopGarageBandPlayback();
      applyGarageBandSnapshot(snapshot);
      renderGarageBandProject();
    }

    function copyGarageBandSelection() {
      const selected = getSelectedGarageBandClip();
      if (!selected) {
        const track = getSelectedGarageBandTrack();
        if (track) {
          simulatedClipboard.text = track.name;
        }
        return;
      }
      garageBandClipboardClip = cloneGarageBandClip(selected.clip);
      const loop = getGarageBandLoop(selected.clip.loopId);
      simulatedClipboard.text = loop ? loop.name : '';
    }

    function cutGarageBandSelection() {
      copyGarageBandSelection();
      removeGarageBandClip();
    }

    function pasteGarageBandSelection() {
      if (!garageBandClipboardClip) {
        return;
      }
      pushGarageBandUndoSnapshot();
      let track = getSelectedGarageBandTrack();
      if (!track) {
        track = createGarageBandTrack();
        garageBandTracks.push(track);
      }
      const clip = createGarageBandClip(
        garageBandClipboardClip.loopId,
        getGarageBandTrackEnd(track),
        garageBandClipboardClip.duration
      );
      track.clips.push(clip);
      garageBandSelectedClipInstanceId = clip.instanceId;
      garageBandSelectedTrackId = track.id;
      renderGarageBandProject();
    }

    function selectAllGarageBandClips() {
      const track = getSelectedGarageBandTrack() || garageBandTracks[0];
      if (!track) {
        return;
      }
      garageBandSelectedTrackId = track.id;
      garageBandSelectedClipInstanceId = track.clips[0] ? track.clips[0].instanceId : null;
      renderGarageBandProject();
    }

    function loadGarageBandProject(fileSystemObject) {
      garageBandCurrentFileSystemObject = fileSystemObject || null;
      const stored = fileSystemObject
        ? simulatedGarageBandProjects.get(fileSystemObject)
        : null;
      stopGarageBandPlaybackTimer();
      garageBandPlaybackState = 'stopped';
      garageBandPlayheadPosition = 0;
      if (stored && Array.isArray(stored.tracks)) {
        garageBandTracks = cloneGarageBandTracks(stored.tracks);
        garageBandSelectedTrackId = stored.selectedTrackId || (garageBandTracks[0] ? garageBandTracks[0].id : null);
        garageBandSelectedClipInstanceId = stored.selectedClipInstanceId || null;
        garageBandSelectedInstrumentId = stored.selectedInstrumentId || (garageBandTracks[0] ? garageBandTracks[0].instrumentId : simulatedGarageBandInstruments[0].id);
        garageBandSelectedLoopId = stored.selectedLoopId || simulatedGarageBandLoops[0].id;
      } else {
        garageBandTracks = getDefaultGarageBandTracks();
        garageBandSelectedTrackId = garageBandTracks[0].id;
        garageBandSelectedClipInstanceId = null;
        garageBandSelectedInstrumentId = garageBandTracks[0].instrumentId;
        garageBandSelectedLoopId = simulatedGarageBandLoops[0].id;
      }
      garageBandUndoHistory = [];
      renderGarageBandProject();
      if (fileSystemObject) {
        recordSimulatedRecentItem(fileSystemObject);
      }
    }

    function getGarageBandProjectPayload() {
      return Object.freeze({
        selectedTrackId: garageBandSelectedTrackId,
        selectedClipInstanceId: garageBandSelectedClipInstanceId,
        selectedInstrumentId: garageBandSelectedInstrumentId,
        selectedLoopId: garageBandSelectedLoopId,
        tracks: Object.freeze(cloneGarageBandTracks(garageBandTracks).map((track) => Object.freeze({
          id: track.id,
          name: track.name,
          instrumentId: track.instrumentId,
          volume: track.volume,
          muted: track.muted,
          solo: track.solo,
          clips: Object.freeze(track.clips.map((clip) => Object.freeze(clip)))
        })))
      });
    }

    function getGarageBandProjectPlainLength(payload) {
      return payload.tracks.reduce((sum, track) => (
        sum + String(track.name).length + track.clips.length + track.volume
      ), 0);
    }

    function normalizeGarageBandDocumentName(desiredName) {
      let name = typeof desiredName === 'string' ? desiredName : '';
      name = name.split('/').join('').split('\\').join('').trim();
      if (!name) {
        name = 'Untitled';
      }
      if (name.slice(-5) !== '.band') {
        name += '.band';
      }
      return name;
    }

    function getAvailableGarageBandDocumentName(parentFileSystemObject, desiredName) {
      const existingNames = new Set(
        getFileSystemObjectChildren(parentFileSystemObject).map((child) => child.name)
      );
      const baseName = normalizeGarageBandDocumentName(desiredName);
      if (!existingNames.has(baseName)) {
        return baseName;
      }
      const withoutSuffix = baseName.slice(0, -5);
      let nextNumber = 2;
      while (existingNames.has(`${withoutSuffix} ${nextNumber}.band`)) {
        nextNumber += 1;
      }
      return `${withoutSuffix} ${nextNumber}.band`;
    }

    function createGarageBandDocumentFileSystemObject(documentName, plainTextLength) {
      return Object.freeze({
        name: documentName,
        type: 'file',
        createdAt: takeSimulatedModificationTimestamp(),
        modifiedAt: takeSimulatedModificationTimestamp(),
        size: plainTextLength || 1,
        label: simulatedNoLabel
      });
    }

    function saveGarageBandProjectToFileSystemObject(fileSystemObject) {
      if (!fileSystemObject) {
        return;
      }
      const payload = getGarageBandProjectPayload();
      simulatedGarageBandProjects.set(fileSystemObject, payload);
      garageBandCurrentFileSystemObject = fileSystemObject;
      updateGarageBandWindowTitle();
      recordSimulatedRecentItem(fileSystemObject);
      refreshOpenFinderWindows();
    }

    function saveGarageBandProject() {
      if (garageBandCurrentFileSystemObject) {
        saveGarageBandProjectToFileSystemObject(garageBandCurrentFileSystemObject);
        return;
      }
      const payload = getGarageBandProjectPayload();
      const newFileSystemObject = createGarageBandDocumentFileSystemObject(
        getAvailableGarageBandDocumentName(documentsFileSystemObject, 'Untitled.band'),
        getGarageBandProjectPlainLength(payload)
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      saveGarageBandProjectToFileSystemObject(newFileSystemObject);
    }

    function saveGarageBandProjectAs(desiredName) {
      const payload = getGarageBandProjectPayload();
      const documentName = getAvailableGarageBandDocumentName(
        documentsFileSystemObject,
        desiredName
      );
      if (
        garageBandCurrentFileSystemObject &&
        garageBandCurrentFileSystemObject.name === documentName
      ) {
        saveGarageBandProjectToFileSystemObject(garageBandCurrentFileSystemObject);
        return;
      }
      const newFileSystemObject = createGarageBandDocumentFileSystemObject(
        documentName,
        getGarageBandProjectPlainLength(payload)
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      saveGarageBandProjectToFileSystemObject(newFileSystemObject);
    }

    function showGarageBandWindow(fileSystemObject) {
      recordSimulatedRecentItem(garageBandApplicationIdentity);
      const existingGarageBandWindow = getGarageBandWindow();
      if (existingGarageBandWindow && existingGarageBandWindow.isConnected) {
        if (fileSystemObject) {
          loadGarageBandProject(fileSystemObject);
        }
        focusFinderWindow(existingGarageBandWindow);
        return;
      }

      const garageBandWindow = document.createElement('section');
      garageBandWindow.id = 'garageband-window';
      garageBandWindow.className = 'finder-window garageband-window';
      garageBandWindow.setAttribute('role', 'dialog');
      garageBandWindow.setAttribute('aria-labelledby', 'garageband-window-title');
      garageBandWindow.setAttribute('data-garageband-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(garageBandWindow);
      });
      const title = document.createElement('div');
      title.id = 'garageband-window-title';
      title.className = 'finder-title';
      title.textContent = 'Untitled';
      titleBar.append(closeButton, title);

      const toolbar = document.createElement('div');
      toolbar.className = 'garageband-toolbar';
      function createGarageBandToolButton(id, label, ariaLabel, action) {
        const button = document.createElement('button');
        button.type = 'button';
        button.id = id;
        button.className = 'garageband-tool-button';
        button.textContent = label;
        button.setAttribute('aria-label', ariaLabel);
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          action();
        });
        return button;
      }
      toolbar.append(
        createGarageBandToolButton('garageband-play-button', 'Play', 'Play', playGarageBandPreview),
        createGarageBandToolButton('garageband-stop-button', 'Stop', 'Stop', stopGarageBandPlayback),
        createGarageBandToolButton('garageband-new-track-button', 'New Track', 'New Track', addGarageBandTrack),
        createGarageBandToolButton('garageband-add-loop-button', 'Add Loop', 'Add Loop', () => {
          addGarageBandLoop(garageBandSelectedLoopId);
        })
      );

      const body = document.createElement('div');
      body.className = 'garageband-body';
      const main = document.createElement('div');
      main.className = 'garageband-main';
      const trackList = document.createElement('div');
      trackList.className = 'garageband-track-list';
      trackList.id = 'garageband-track-list';
      const timelineWrap = document.createElement('div');
      timelineWrap.className = 'garageband-timeline-wrap';
      const timeline = document.createElement('div');
      timeline.className = 'garageband-timeline';
      timeline.id = 'garageband-timeline';
      timelineWrap.appendChild(timeline);
      main.append(trackList, timelineWrap);

      const browser = document.createElement('div');
      browser.className = 'garageband-browser';
      const instrumentPane = document.createElement('div');
      instrumentPane.className = 'garageband-browser-pane';
      const instrumentHeading = document.createElement('div');
      instrumentHeading.className = 'garageband-browser-heading';
      instrumentHeading.textContent = 'INSTRUMENTS';
      const instrumentList = document.createElement('div');
      instrumentList.className = 'garageband-browser-list';
      instrumentList.id = 'garageband-instrument-list';
      instrumentPane.append(instrumentHeading, instrumentList);
      const loopPane = document.createElement('div');
      loopPane.className = 'garageband-browser-pane';
      const loopHeading = document.createElement('div');
      loopHeading.className = 'garageband-browser-heading';
      loopHeading.textContent = 'LOOPS';
      const loopList = document.createElement('div');
      loopList.className = 'garageband-browser-list';
      loopList.id = 'garageband-loop-list';
      loopPane.append(loopHeading, loopList);
      browser.append(instrumentPane, loopPane);

      const status = document.createElement('div');
      status.className = 'garageband-status';
      status.id = 'garageband-status';

      body.append(main, browser, status);
      garageBandWindow.append(titleBar, toolbar, body);
      document.body.appendChild(garageBandWindow);
      enableWindowFocus(garageBandWindow);
      makeWindowDraggable(garageBandWindow, titleBar);
      if (fileSystemObject) {
        loadGarageBandProject(fileSystemObject);
      } else {
        startNewGarageBandProject();
      }
    }

    function activateGarageBandFromDock() {
      const garageBandWindow = getGarageBandWindow();
      if (garageBandWindow && garageBandWindow.isConnected) {
        recordSimulatedRecentItem(garageBandApplicationIdentity);
        focusFinderWindow(garageBandWindow);
        return;
      }
      showGarageBandWindow();
    }

    function hideGarageBandWindow() {
      const garageBandWindow = getGarageBandWindow();
      if (garageBandWindow && garageBandWindow.isConnected && !garageBandWindow.classList.contains('is-minimized')) {
        minimizeFinderWindow(garageBandWindow);
      }
    }

    function quitGarageBandWindow() {
      const garageBandWindow = getGarageBandWindow();
      if (garageBandWindow && garageBandWindow.isConnected) {
        closeFinderWindow(garageBandWindow);
      }
    }

    function showAboutGarageBandWindow() {
      const existingAboutWindow = document.getElementById('about-garageband-window');
      if (existingAboutWindow && existingAboutWindow.isConnected) {
        focusFinderWindow(existingAboutWindow);
        return;
      }
      const aboutWindow = document.createElement('section');
      aboutWindow.id = 'about-garageband-window';
      aboutWindow.className = 'finder-window about-garageband-window';
      aboutWindow.setAttribute('role', 'dialog');
      aboutWindow.setAttribute('aria-labelledby', 'about-garageband-window-title');
      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(aboutWindow);
      });
      const title = document.createElement('div');
      title.id = 'about-garageband-window-title';
      title.className = 'finder-title';
      title.textContent = 'About GarageBand';
      const content = document.createElement('div');
      content.className = 'finder-content about-finder-content';
      const heading = document.createElement('div');
      heading.className = 'about-finder-heading';
      heading.textContent = 'GarageBand';
      const copy = document.createElement('p');
      copy.className = 'about-finder-copy';
      copy.textContent = 'A simulated Mac OS X Tiger-style GarageBand studio.';
      content.append(heading, copy);
      titleBar.append(closeButton, title);
      aboutWindow.append(titleBar, content);
      document.body.appendChild(aboutWindow);
      enableWindowFocus(aboutWindow);
      makeWindowDraggable(aboutWindow, titleBar);
    }

    function collectGarageBandDocuments() {
      const collected = [];
      collectSimulatedFileSystemHierarchy(macintoshHDFileSystemObject, collected);
      collectSimulatedFileSystemHierarchy(homeFileSystemObject, collected);
      return collected.filter((fileSystemObject) => isGarageBandDocument(fileSystemObject));
    }

    function showGarageBandOpenWindow() {
      const existingOpenWindow = document.getElementById('garageband-open-window');
      if (existingOpenWindow && existingOpenWindow.isConnected) {
        focusFinderWindow(existingOpenWindow);
        return;
      }
      const openWindow = document.createElement('section');
      openWindow.id = 'garageband-open-window';
      openWindow.className = 'finder-window garageband-open-window';
      openWindow.setAttribute('role', 'dialog');
      openWindow.setAttribute('aria-labelledby', 'garageband-open-window-title');
      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(openWindow);
      });
      const title = document.createElement('div');
      title.id = 'garageband-open-window-title';
      title.className = 'finder-title';
      title.textContent = 'Open';
      const content = document.createElement('div');
      content.className = 'finder-content garageband-open-content';
      const list = document.createElement('div');
      list.className = 'garageband-open-list';
      list.setAttribute('role', 'listbox');
      list.setAttribute('aria-label', 'GarageBand projects');
      const files = collectGarageBandDocuments();
      garageBandOpenSelectedFileSystemObject = files[0] || null;
      files.forEach((fileSystemObject, fileIndex) => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'garageband-open-file';
        item.textContent = fileSystemObject.name;
        item.setAttribute('role', 'option');
        if (fileIndex === 0) {
          item.classList.add('is-selected');
        }
        item.addEventListener('click', (event) => {
          event.stopPropagation();
          garageBandOpenSelectedFileSystemObject = fileSystemObject;
          list.querySelectorAll('.garageband-open-file').forEach((fileItem) => {
            fileItem.classList.toggle('is-selected', fileItem === item);
          });
        });
        item.addEventListener('dblclick', (event) => {
          event.stopPropagation();
          garageBandOpenSelectedFileSystemObject = fileSystemObject;
          closeFinderWindow(openWindow);
          showGarageBandWindow(fileSystemObject);
        });
        list.appendChild(item);
      });
      const actions = document.createElement('div');
      actions.className = 'garageband-open-actions';
      const openButton = document.createElement('button');
      openButton.type = 'button';
      openButton.className = 'garageband-tool-button';
      openButton.textContent = 'Open';
      openButton.addEventListener('click', (event) => {
        event.stopPropagation();
        const selectedFileSystemObject = garageBandOpenSelectedFileSystemObject;
        closeFinderWindow(openWindow);
        if (selectedFileSystemObject) {
          showGarageBandWindow(selectedFileSystemObject);
        }
      });
      actions.appendChild(openButton);
      content.append(list, actions);
      titleBar.append(closeButton, title);
      openWindow.append(titleBar, content);
      document.body.appendChild(openWindow);
      enableWindowFocus(openWindow);
      makeWindowDraggable(openWindow, titleBar);
    }

    function showGarageBandSaveAsWindow() {
      const existingSaveAsWindow = document.getElementById('garageband-save-as-window');
      if (existingSaveAsWindow && existingSaveAsWindow.isConnected) {
        focusFinderWindow(existingSaveAsWindow);
        return;
      }
      const saveAsWindow = document.createElement('section');
      saveAsWindow.id = 'garageband-save-as-window';
      saveAsWindow.className = 'finder-window garageband-save-as-window';
      saveAsWindow.setAttribute('role', 'dialog');
      saveAsWindow.setAttribute('aria-labelledby', 'garageband-save-as-window-title');
      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(saveAsWindow);
      });
      const title = document.createElement('div');
      title.id = 'garageband-save-as-window-title';
      title.className = 'finder-title';
      title.textContent = 'Save As';
      const content = document.createElement('div');
      content.className = 'finder-content garageband-save-as-content';
      const label = document.createElement('div');
      label.className = 'garageband-save-as-label';
      label.textContent = 'Save as:';
      const nameField = document.createElement('input');
      nameField.type = 'text';
      nameField.id = 'garageband-save-as-name';
      nameField.className = 'garageband-save-as-name';
      nameField.setAttribute('aria-label', 'Project name');
      nameField.value = garageBandCurrentFileSystemObject
        ? garageBandCurrentFileSystemObject.name
        : 'Untitled.band';
      nameField.addEventListener('click', (event) => {
        event.stopPropagation();
      });
      nameField.addEventListener('keydown', (event) => {
        event.stopPropagation();
        if (event.key === 'Enter') {
          event.preventDefault();
          const nextName = nameField.value;
          closeFinderWindow(saveAsWindow);
          saveGarageBandProjectAs(nextName);
        }
      });
      const actions = document.createElement('div');
      actions.className = 'garageband-save-as-actions';
      const saveButton = document.createElement('button');
      saveButton.type = 'button';
      saveButton.className = 'garageband-tool-button';
      saveButton.id = 'garageband-save-as-button';
      saveButton.textContent = 'Save';
      saveButton.addEventListener('click', (event) => {
        event.stopPropagation();
        const nextName = nameField.value;
        closeFinderWindow(saveAsWindow);
        saveGarageBandProjectAs(nextName);
      });
      actions.appendChild(saveButton);
      content.append(label, nameField, actions);
      titleBar.append(closeButton, title);
      saveAsWindow.append(titleBar, content);
      document.body.appendChild(saveAsWindow);
      enableWindowFocus(saveAsWindow);
      makeWindowDraggable(saveAsWindow, titleBar);
      nameField.focus();
      nameField.select();
    }

