    function syncGarageBandDockContextMenuAvailability() {
      const garageBandWindow = getGarageBandWindow();
      const garageBandIsRunning = Boolean(garageBandWindow && garageBandWindow.isConnected);
      const garageBandIsVisible = garageBandIsRunning && !garageBandWindow.classList.contains('is-minimized');
      setDockContextMenuItemAvailable(garageBandDockShowAllWindowsMenuItem, garageBandIsRunning);
      setDockContextMenuItemAvailable(garageBandDockHideMenuItem, garageBandIsVisible);
      setDockContextMenuItemAvailable(garageBandDockQuitMenuItem, garageBandIsRunning);
    }

    function openGarageBandDockContextMenu(event) {
      event.preventDefault();
      event.stopPropagation();
      closeAllMenuDropdowns();
      syncGarageBandDockContextMenuAvailability();
      positionDockContextMenu(garageBandDockContextMenu, garageBandDockItem);
      garageBandDockContextMenu.hidden = false;
    }

    const simulatedIDVDThemes = Object.freeze([
      Object.freeze({ id: 'idvd-theme-theater', name: 'Theater', background: '#5a1424', accent: '#d4a017' }),
      Object.freeze({ id: 'idvd-theme-travel', name: 'Travel', background: '#0a4a7a', accent: '#f4d36a' }),
      Object.freeze({ id: 'idvd-theme-wedding', name: 'Wedding', background: '#7a5a62', accent: '#f4e0d0' }),
      Object.freeze({ id: 'idvd-theme-sports', name: 'Sports', background: '#1e5a28', accent: '#d8f08a' }),
      Object.freeze({ id: 'idvd-theme-kids', name: 'Kids', background: '#3a3a8a', accent: '#f4c36a' }),
      Object.freeze({ id: 'idvd-theme-graphite', name: 'Graphite Lounge', background: '#2c3036', accent: '#c8c8c8' }),
      Object.freeze({ id: 'idvd-theme-aqua', name: 'Aqua Reflections', background: '#07589c', accent: '#9ee0f4' }),
      Object.freeze({ id: 'idvd-theme-scrapbook', name: 'Scrapbook', background: '#6a4a28', accent: '#f0d2a0' })
    ]);

    const simulatedIDVDLibraryMovies = Object.freeze([
      Object.freeze({ id: 'idvd-movie-aqua', name: 'Aqua Afternoon', duration: 8, size: 420 }),
      Object.freeze({ id: 'idvd-movie-tiger', name: 'Tiger Stripe', duration: 6, size: 310 }),
      Object.freeze({ id: 'idvd-movie-dockside', name: 'Dockside', duration: 10, size: 540 }),
      Object.freeze({ id: 'idvd-movie-spotlight', name: 'Spotlight', duration: 5, size: 260 }),
      Object.freeze({ id: 'idvd-movie-safari', name: 'Safari Wind', duration: 7, size: 380 }),
      Object.freeze({ id: 'idvd-movie-graphite', name: 'Graphite Sky', duration: 4, size: 210 }),
      Object.freeze({ id: 'idvd-movie-holiday', name: 'Holiday Reel', duration: 12, size: 640 }),
      Object.freeze({ id: 'idvd-movie-picnic', name: 'Family Picnic', duration: 9, size: 490 })
    ]);

    const iDVDCapacityMax = 4700;
    let iDVDCurrentFileSystemObject = null;
    let iDVDOpenSelectedFileSystemObject = null;
    let iDVDTitle = 'My DVD';
    let iDVDSelectedThemeId = simulatedIDVDThemes[0].id;
    let iDVDProjectMovies = [];
    let iDVDSelectedMovieInstanceId = null;
    let iDVDSelectedLibraryMovieId = simulatedIDVDLibraryMovies[0].id;
    let iDVDClipboardMovie = null;
    let iDVDUndoHistory = [];
    let iDVDPreviewState = 'menu';
    let iDVDPreviewMovieInstanceId = null;
    let nextIDVDMovieSequence = 1;

    function isIDVDDocument(fileSystemObject) {
      return Boolean(
        fileSystemObject &&
        fileSystemObject.type === 'file' &&
        typeof fileSystemObject.name === 'string' &&
        fileSystemObject.name.slice(-8) === '.dvdproj'
      );
    }

    function getIDVDIconMarkup() {
      return `
        <svg viewBox="0 0 72 72" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <circle cx="36" cy="36" r="26" fill="#6a6ea0" stroke="#2a2e4a"/>
          <circle cx="36" cy="36" r="26" fill="none" stroke="#d8dce8" stroke-width="3" opacity="0.35"/>
          <circle cx="36" cy="36" r="8" fill="#dfe3ea" stroke="#4a4e62"/>
          <circle cx="36" cy="36" r="3" fill="#2a2e4a"/>
        </svg>
      `;
    }

    function getIDVDWindow() {
      return document.getElementById('idvd-window');
    }

    function getIDVDTheme(themeId) {
      return simulatedIDVDThemes.find((theme) => theme.id === themeId) || simulatedIDVDThemes[0];
    }

    function getIDVDLibraryMovie(movieId) {
      return simulatedIDVDLibraryMovies.find((movie) => movie.id === movieId) || null;
    }

    function cloneIDVDMovie(item) {
      return {
        instanceId: item.instanceId,
        movieId: item.movieId
      };
    }

    function snapshotIDVDProject() {
      return {
        title: iDVDTitle,
        themeId: iDVDSelectedThemeId,
        movies: iDVDProjectMovies.map(cloneIDVDMovie),
        selectedMovieInstanceId: iDVDSelectedMovieInstanceId,
        selectedLibraryMovieId: iDVDSelectedLibraryMovieId,
        previewState: iDVDPreviewState,
        previewMovieInstanceId: iDVDPreviewMovieInstanceId
      };
    }

    function applyIDVDSnapshot(snapshot) {
      iDVDTitle = snapshot.title;
      iDVDSelectedThemeId = snapshot.themeId;
      iDVDProjectMovies = snapshot.movies.map(cloneIDVDMovie);
      iDVDSelectedMovieInstanceId = snapshot.selectedMovieInstanceId;
      iDVDSelectedLibraryMovieId = snapshot.selectedLibraryMovieId || simulatedIDVDLibraryMovies[0].id;
      iDVDPreviewState = snapshot.previewState || 'menu';
      iDVDPreviewMovieInstanceId = snapshot.previewMovieInstanceId || null;
    }

    function pushIDVDUndoSnapshot() {
      iDVDUndoHistory.push(snapshotIDVDProject());
      if (iDVDUndoHistory.length > 20) {
        iDVDUndoHistory.shift();
      }
    }

    function resetIDVDSessionState() {
      iDVDCurrentFileSystemObject = null;
      iDVDOpenSelectedFileSystemObject = null;
      iDVDTitle = 'My DVD';
      iDVDSelectedThemeId = simulatedIDVDThemes[0].id;
      iDVDProjectMovies = [];
      iDVDSelectedMovieInstanceId = null;
      iDVDSelectedLibraryMovieId = simulatedIDVDLibraryMovies[0].id;
      iDVDClipboardMovie = null;
      iDVDUndoHistory = [];
      iDVDPreviewState = 'menu';
      iDVDPreviewMovieInstanceId = null;
    }

    function createIDVDMovieItem(movieId) {
      const item = {
        instanceId: `idvd-item-${nextIDVDMovieSequence}`,
        movieId
      };
      nextIDVDMovieSequence += 1;
      return item;
    }

    function getSelectedIDVDMovieIndex() {
      return iDVDProjectMovies.findIndex((item) => item.instanceId === iDVDSelectedMovieInstanceId);
    }

    function getIDVDUsedCapacity() {
      return iDVDProjectMovies.reduce((sum, item) => {
        const movie = getIDVDLibraryMovie(item.movieId);
        return sum + (movie ? movie.size : 0);
      }, 0);
    }

    function updateIDVDWindowTitle() {
      const iDVDWindow = getIDVDWindow();
      const title = iDVDWindow && iDVDWindow.querySelector('.finder-title');
      if (title) {
        title.textContent = iDVDCurrentFileSystemObject
          ? iDVDCurrentFileSystemObject.name
          : 'Untitled';
      }
    }

    function renderIDVDMediaList() {
      const list = document.getElementById('idvd-media-list');
      if (!list) {
        return;
      }
      list.replaceChildren();
      simulatedIDVDLibraryMovies.forEach((movie) => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'idvd-media-item';
        item.setAttribute('data-movie-id', movie.id);
        item.setAttribute('aria-label', movie.name);
        item.classList.toggle('is-selected', movie.id === iDVDSelectedLibraryMovieId);
        const name = document.createElement('div');
        name.textContent = movie.name;
        const meta = document.createElement('div');
        meta.className = 'idvd-item-meta';
        meta.textContent = `${movie.duration} min · ${movie.size} MB`;
        item.append(name, meta);
        item.addEventListener('click', (event) => {
          event.stopPropagation();
          iDVDSelectedLibraryMovieId = movie.id;
          renderIDVDProject();
        });
        item.addEventListener('dblclick', (event) => {
          event.stopPropagation();
          iDVDSelectedLibraryMovieId = movie.id;
          addIDVDMovie(movie.id);
        });
        list.appendChild(item);
      });
    }

    function renderIDVDMovieList() {
      const list = document.getElementById('idvd-movie-list');
      if (!list) {
        return;
      }
      list.replaceChildren();
      iDVDProjectMovies.forEach((item, itemIndex) => {
        const movie = getIDVDLibraryMovie(item.movieId);
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'idvd-movie-item';
        button.setAttribute('data-instance-id', item.instanceId);
        button.setAttribute('data-movie-id', item.movieId);
        button.setAttribute('data-movie-index', String(itemIndex));
        button.setAttribute('aria-label', movie ? movie.name : 'Movie');
        button.classList.toggle('is-selected', item.instanceId === iDVDSelectedMovieInstanceId);
        const name = document.createElement('div');
        name.textContent = movie ? movie.name : 'Movie';
        const meta = document.createElement('div');
        meta.className = 'idvd-item-meta';
        meta.textContent = movie ? `${movie.duration} min` : '';
        button.append(name, meta);
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          iDVDSelectedMovieInstanceId = item.instanceId;
          iDVDSelectedLibraryMovieId = item.movieId;
          renderIDVDProject();
        });
        list.appendChild(button);
      });
    }

    function renderIDVDThemeList() {
      const list = document.getElementById('idvd-theme-list');
      if (!list) {
        return;
      }
      list.replaceChildren();
      simulatedIDVDThemes.forEach((theme) => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'idvd-theme-item';
        item.setAttribute('data-theme-id', theme.id);
        item.setAttribute('aria-label', theme.name);
        item.classList.toggle('is-selected', theme.id === iDVDSelectedThemeId);
        item.textContent = theme.name;
        item.addEventListener('click', (event) => {
          event.stopPropagation();
          setIDVDTheme(theme.id);
        });
        list.appendChild(item);
      });
    }

    function renderIDVDCanvas() {
      const canvas = document.getElementById('idvd-canvas');
      if (!canvas) {
        return;
      }
      const theme = getIDVDTheme(iDVDSelectedThemeId);
      canvas.style.background = `radial-gradient(circle at 30% 20%, ${theme.accent}, ${theme.background} 62%)`;
      canvas.setAttribute('data-theme-id', theme.id);
      canvas.setAttribute('data-dvd-title', iDVDTitle);
      canvas.replaceChildren();
      if (iDVDPreviewState === 'playing') {
        const playing = iDVDProjectMovies.find((item) => item.instanceId === iDVDPreviewMovieInstanceId);
        const movie = playing ? getIDVDLibraryMovie(playing.movieId) : null;
        const overlay = document.createElement('div');
        overlay.className = 'idvd-now-playing';
        overlay.id = 'idvd-now-playing';
        const label = document.createElement('div');
        label.textContent = movie ? `Now Playing: ${movie.name}` : 'Now Playing';
        const menuButton = document.createElement('button');
        menuButton.type = 'button';
        menuButton.className = 'idvd-tool-button';
        menuButton.id = 'idvd-menu-return-button';
        menuButton.textContent = 'Menu';
        menuButton.addEventListener('click', (event) => {
          event.stopPropagation();
          iDVDPreviewState = 'preview';
          iDVDPreviewMovieInstanceId = null;
          renderIDVDProject();
        });
        overlay.append(label, menuButton);
        canvas.appendChild(overlay);
        return;
      }
      const title = document.createElement('div');
      title.className = 'idvd-canvas-title';
      title.id = 'idvd-canvas-title';
      title.textContent = iDVDTitle || 'Untitled DVD';
      const movies = document.createElement('div');
      movies.className = 'idvd-canvas-movies';
      iDVDProjectMovies.forEach((item) => {
        const movie = getIDVDLibraryMovie(item.movieId);
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'idvd-menu-button';
        button.setAttribute('data-instance-id', item.instanceId);
        button.setAttribute('data-movie-id', item.movieId);
        button.classList.toggle('is-selected', item.instanceId === iDVDSelectedMovieInstanceId);
        button.textContent = movie ? movie.name : 'Movie';
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          iDVDSelectedMovieInstanceId = item.instanceId;
          if (iDVDPreviewState === 'preview') {
            iDVDPreviewState = 'playing';
            iDVDPreviewMovieInstanceId = item.instanceId;
          }
          renderIDVDProject();
        });
        movies.appendChild(button);
      });
      canvas.append(title, movies);
    }

    function renderIDVDCapacity() {
      const status = document.getElementById('idvd-capacity');
      const fill = document.getElementById('idvd-capacity-fill');
      const used = getIDVDUsedCapacity();
      if (status) {
        status.textContent = `${used} MB of ${iDVDCapacityMax} MB`;
        status.setAttribute('data-used-mb', String(used));
      }
      if (fill) {
        const percent = Math.min(100, Math.round((used / iDVDCapacityMax) * 100));
        fill.style.width = `${percent}%`;
        fill.classList.toggle('is-full', used > iDVDCapacityMax);
      }
    }

    function renderIDVDChrome() {
      const iDVDWindow = getIDVDWindow();
      const titleField = document.getElementById('idvd-title-field');
      const previewButton = document.getElementById('idvd-preview-button');
      if (titleField && document.activeElement !== titleField) {
        titleField.value = iDVDTitle;
      }
      if (previewButton) {
        previewButton.classList.toggle('is-active', iDVDPreviewState === 'preview' || iDVDPreviewState === 'playing');
      }
      if (iDVDWindow) {
        iDVDWindow.setAttribute('data-idvd-theme', iDVDSelectedThemeId);
        iDVDWindow.setAttribute('data-idvd-preview', iDVDPreviewState);
        iDVDWindow.setAttribute('data-idvd-title', iDVDTitle);
      }
    }

    function renderIDVDProject() {
      renderIDVDMediaList();
      renderIDVDMovieList();
      renderIDVDThemeList();
      renderIDVDCanvas();
      renderIDVDCapacity();
      renderIDVDChrome();
      updateIDVDWindowTitle();
    }

    function getDefaultIDVDMovies() {
      return [
        createIDVDMovieItem('idvd-movie-aqua'),
        createIDVDMovieItem('idvd-movie-tiger'),
        createIDVDMovieItem('idvd-movie-dockside')
      ];
    }

    function startNewIDVDProject() {
      resetIDVDSessionState();
      iDVDProjectMovies = getDefaultIDVDMovies();
      iDVDSelectedMovieInstanceId = iDVDProjectMovies[0].instanceId;
      renderIDVDProject();
    }

    function setIDVDTheme(themeId) {
      const theme = getIDVDTheme(themeId);
      if (!theme || theme.id === iDVDSelectedThemeId) {
        iDVDSelectedThemeId = theme.id;
        renderIDVDProject();
        return;
      }
      pushIDVDUndoSnapshot();
      iDVDSelectedThemeId = theme.id;
      renderIDVDProject();
    }

    function cycleIDVDTheme() {
      const index = simulatedIDVDThemes.findIndex((theme) => theme.id === iDVDSelectedThemeId);
      const next = simulatedIDVDThemes[(index + 1) % simulatedIDVDThemes.length];
      setIDVDTheme(next.id);
    }

    function setIDVDTitle(nextTitle) {
      const title = typeof nextTitle === 'string' ? nextTitle : '';
      if (title === iDVDTitle) {
        return;
      }
      pushIDVDUndoSnapshot();
      iDVDTitle = title;
      renderIDVDProject();
    }

    function addIDVDMovie(movieId) {
      const movie = getIDVDLibraryMovie(movieId || iDVDSelectedLibraryMovieId);
      if (!movie) {
        return;
      }
      pushIDVDUndoSnapshot();
      iDVDSelectedLibraryMovieId = movie.id;
      const item = createIDVDMovieItem(movie.id);
      iDVDProjectMovies.push(item);
      iDVDSelectedMovieInstanceId = item.instanceId;
      renderIDVDProject();
    }

    function removeIDVDMovie() {
      const index = getSelectedIDVDMovieIndex();
      if (index < 0) {
        return;
      }
      pushIDVDUndoSnapshot();
      iDVDProjectMovies.splice(index, 1);
      const next = iDVDProjectMovies[Math.min(index, iDVDProjectMovies.length - 1)];
      iDVDSelectedMovieInstanceId = next ? next.instanceId : null;
      renderIDVDProject();
    }

    function moveIDVDMovie(offset) {
      const index = getSelectedIDVDMovieIndex();
      const nextIndex = index + offset;
      if (index < 0 || nextIndex < 0 || nextIndex >= iDVDProjectMovies.length) {
        return;
      }
      pushIDVDUndoSnapshot();
      const [item] = iDVDProjectMovies.splice(index, 1);
      iDVDProjectMovies.splice(nextIndex, 0, item);
      iDVDSelectedMovieInstanceId = item.instanceId;
      renderIDVDProject();
    }

    function previewIDVDProject() {
      iDVDPreviewState = iDVDPreviewState === 'menu' ? 'preview' : 'menu';
      iDVDPreviewMovieInstanceId = null;
      renderIDVDProject();
    }

    function undoIDVDProject() {
      const snapshot = iDVDUndoHistory.pop();
      if (!snapshot) {
        return;
      }
      applyIDVDSnapshot(snapshot);
      renderIDVDProject();
    }

    function copyIDVDSelection() {
      const index = getSelectedIDVDMovieIndex();
      if (index < 0) {
        simulatedClipboard.text = iDVDTitle;
        return;
      }
      const item = iDVDProjectMovies[index];
      iDVDClipboardMovie = cloneIDVDMovie(item);
      const movie = getIDVDLibraryMovie(item.movieId);
      simulatedClipboard.text = movie ? movie.name : iDVDTitle;
    }

    function cutIDVDSelection() {
      copyIDVDSelection();
      removeIDVDMovie();
    }

    function pasteIDVDSelection() {
      if (!iDVDClipboardMovie) {
        return;
      }
      pushIDVDUndoSnapshot();
      const item = createIDVDMovieItem(iDVDClipboardMovie.movieId);
      iDVDProjectMovies.push(item);
      iDVDSelectedMovieInstanceId = item.instanceId;
      renderIDVDProject();
    }

    function selectAllIDVDMovies() {
      if (iDVDProjectMovies.length === 0) {
        return;
      }
      iDVDSelectedMovieInstanceId = iDVDProjectMovies[0].instanceId;
      renderIDVDProject();
    }

    function loadIDVDProject(fileSystemObject) {
      iDVDCurrentFileSystemObject = fileSystemObject || null;
      const stored = fileSystemObject
        ? simulatedIDVDProjects.get(fileSystemObject)
        : null;
      iDVDPreviewState = 'menu';
      iDVDPreviewMovieInstanceId = null;
      if (stored && Array.isArray(stored.movies)) {
        iDVDTitle = stored.title || 'My DVD';
        iDVDSelectedThemeId = stored.themeId || simulatedIDVDThemes[0].id;
        iDVDProjectMovies = stored.movies.map(cloneIDVDMovie);
        iDVDSelectedMovieInstanceId = stored.selectedMovieInstanceId || (iDVDProjectMovies[0] ? iDVDProjectMovies[0].instanceId : null);
      } else {
        iDVDTitle = 'My DVD';
        iDVDSelectedThemeId = simulatedIDVDThemes[0].id;
        iDVDProjectMovies = getDefaultIDVDMovies();
        iDVDSelectedMovieInstanceId = iDVDProjectMovies[0].instanceId;
      }
      iDVDUndoHistory = [];
      renderIDVDProject();
      if (fileSystemObject) {
        recordSimulatedRecentItem(fileSystemObject);
      }
    }

    function getIDVDProjectPayload() {
      return Object.freeze({
        title: iDVDTitle,
        themeId: iDVDSelectedThemeId,
        selectedMovieInstanceId: iDVDSelectedMovieInstanceId,
        movies: Object.freeze(iDVDProjectMovies.map((item) => Object.freeze(cloneIDVDMovie(item))))
      });
    }

    function getIDVDProjectPlainLength(payload) {
      return String(payload.title).length + payload.movies.length;
    }

    function normalizeIDVDDocumentName(desiredName) {
      let name = typeof desiredName === 'string' ? desiredName : '';
      name = name.split('/').join('').split('\\').join('').trim();
      if (!name) {
        name = 'Untitled';
      }
      if (name.slice(-8) !== '.dvdproj') {
        name += '.dvdproj';
      }
      return name;
    }

    function getAvailableIDVDDocumentName(parentFileSystemObject, desiredName) {
      const existingNames = new Set(
        getFileSystemObjectChildren(parentFileSystemObject).map((child) => child.name)
      );
      const baseName = normalizeIDVDDocumentName(desiredName);
      if (!existingNames.has(baseName)) {
        return baseName;
      }
      const withoutSuffix = baseName.slice(0, -8);
      let nextNumber = 2;
      while (existingNames.has(`${withoutSuffix} ${nextNumber}.dvdproj`)) {
        nextNumber += 1;
      }
      return `${withoutSuffix} ${nextNumber}.dvdproj`;
    }

    function createIDVDDocumentFileSystemObject(documentName, plainTextLength) {
      return Object.freeze({
        name: documentName,
        type: 'file',
        createdAt: takeSimulatedModificationTimestamp(),
        modifiedAt: takeSimulatedModificationTimestamp(),
        size: plainTextLength || 1,
        label: simulatedNoLabel
      });
    }

    function saveIDVDProjectToFileSystemObject(fileSystemObject) {
      if (!fileSystemObject) {
        return;
      }
      const payload = getIDVDProjectPayload();
      simulatedIDVDProjects.set(fileSystemObject, payload);
      iDVDCurrentFileSystemObject = fileSystemObject;
      updateIDVDWindowTitle();
      recordSimulatedRecentItem(fileSystemObject);
      refreshOpenFinderWindows();
    }

    function saveIDVDProject() {
      if (iDVDCurrentFileSystemObject) {
        saveIDVDProjectToFileSystemObject(iDVDCurrentFileSystemObject);
        return;
      }
      const payload = getIDVDProjectPayload();
      const newFileSystemObject = createIDVDDocumentFileSystemObject(
        getAvailableIDVDDocumentName(documentsFileSystemObject, 'Untitled.dvdproj'),
        getIDVDProjectPlainLength(payload)
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      saveIDVDProjectToFileSystemObject(newFileSystemObject);
    }

    function saveIDVDProjectAs(desiredName) {
      const payload = getIDVDProjectPayload();
      const documentName = getAvailableIDVDDocumentName(
        documentsFileSystemObject,
        desiredName
      );
      if (
        iDVDCurrentFileSystemObject &&
        iDVDCurrentFileSystemObject.name === documentName
      ) {
        saveIDVDProjectToFileSystemObject(iDVDCurrentFileSystemObject);
        return;
      }
      const newFileSystemObject = createIDVDDocumentFileSystemObject(
        documentName,
        getIDVDProjectPlainLength(payload)
      );
      appendVirtualFileSystemChild(documentsFileSystemObject, newFileSystemObject);
      saveIDVDProjectToFileSystemObject(newFileSystemObject);
    }

    function showIDVDWindow(fileSystemObject) {
      recordSimulatedRecentItem(iDVDApplicationIdentity);
      const existingIDVDWindow = getIDVDWindow();
      if (existingIDVDWindow && existingIDVDWindow.isConnected) {
        if (fileSystemObject) {
          loadIDVDProject(fileSystemObject);
        }
        focusFinderWindow(existingIDVDWindow);
        return;
      }

      const iDVDWindow = document.createElement('section');
      iDVDWindow.id = 'idvd-window';
      iDVDWindow.className = 'finder-window idvd-window';
      iDVDWindow.setAttribute('role', 'dialog');
      iDVDWindow.setAttribute('aria-labelledby', 'idvd-window-title');
      iDVDWindow.setAttribute('data-idvd-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';
      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(iDVDWindow);
      });
      const title = document.createElement('div');
      title.id = 'idvd-window-title';
      title.className = 'finder-title';
      title.textContent = 'Untitled';
      titleBar.append(closeButton, title);

      const toolbar = document.createElement('div');
      toolbar.className = 'idvd-toolbar';
      function createIDVDToolButton(id, label, ariaLabel, action) {
        const button = document.createElement('button');
        button.type = 'button';
        button.id = id;
        button.className = 'idvd-tool-button';
        button.textContent = label;
        button.setAttribute('aria-label', ariaLabel);
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          action();
        });
        return button;
      }
      const titleField = document.createElement('input');
      titleField.type = 'text';
      titleField.id = 'idvd-title-field';
      titleField.className = 'idvd-title-field';
      titleField.setAttribute('aria-label', 'DVD title');
      titleField.addEventListener('click', (event) => {
        event.stopPropagation();
      });
      titleField.addEventListener('input', (event) => {
        event.stopPropagation();
        iDVDTitle = titleField.value;
        const canvasTitle = document.getElementById('idvd-canvas-title');
        if (canvasTitle) {
          canvasTitle.textContent = iDVDTitle || 'Untitled DVD';
        }
        iDVDWindow.setAttribute('data-idvd-title', iDVDTitle);
      });
      titleField.addEventListener('change', (event) => {
        event.stopPropagation();
        setIDVDTitle(titleField.value);
      });
      toolbar.append(
        createIDVDToolButton('idvd-preview-button', 'Preview', 'Preview', previewIDVDProject),
        createIDVDToolButton('idvd-add-button', 'Add Movie', 'Add Movie', () => {
          addIDVDMovie(iDVDSelectedLibraryMovieId);
        }),
        titleField
      );

      const body = document.createElement('div');
      body.className = 'idvd-body';
      const media = document.createElement('div');
      media.className = 'idvd-media';
      const mediaHeading = document.createElement('div');
      mediaHeading.className = 'idvd-pane-heading';
      mediaHeading.textContent = 'MEDIA';
      const mediaList = document.createElement('div');
      mediaList.className = 'idvd-pane-list';
      mediaList.id = 'idvd-media-list';
      const movieHeading = document.createElement('div');
      movieHeading.className = 'idvd-pane-heading';
      movieHeading.textContent = 'DVD MOVIES';
      const movieList = document.createElement('div');
      movieList.className = 'idvd-pane-list';
      movieList.id = 'idvd-movie-list';
      media.append(mediaHeading, mediaList, movieHeading, movieList);

      const canvasWrap = document.createElement('div');
      canvasWrap.className = 'idvd-canvas-wrap';
      const canvas = document.createElement('div');
      canvas.className = 'idvd-canvas';
      canvas.id = 'idvd-canvas';
      canvas.setAttribute('aria-label', 'DVD menu');
      canvasWrap.appendChild(canvas);

      const themes = document.createElement('div');
      themes.className = 'idvd-themes';
      const themeHeading = document.createElement('div');
      themeHeading.className = 'idvd-pane-heading';
      themeHeading.textContent = 'THEMES';
      const themeList = document.createElement('div');
      themeList.className = 'idvd-pane-list';
      themeList.id = 'idvd-theme-list';
      themes.append(themeHeading, themeList);

      body.append(media, canvasWrap, themes);

      const status = document.createElement('div');
      status.className = 'idvd-status';
      const capacity = document.createElement('div');
      capacity.id = 'idvd-capacity';
      const bar = document.createElement('div');
      bar.className = 'idvd-capacity-bar';
      const fill = document.createElement('div');
      fill.className = 'idvd-capacity-fill';
      fill.id = 'idvd-capacity-fill';
      bar.appendChild(fill);
      status.append(capacity, bar);

      iDVDWindow.append(titleBar, toolbar, body, status);
      document.body.appendChild(iDVDWindow);
      enableWindowFocus(iDVDWindow);
      makeWindowDraggable(iDVDWindow, titleBar);
      if (fileSystemObject) {
        loadIDVDProject(fileSystemObject);
      } else {
        startNewIDVDProject();
      }
    }

    function activateIDVDFromDock() {
      const iDVDWindow = getIDVDWindow();
      if (iDVDWindow && iDVDWindow.isConnected) {
        recordSimulatedRecentItem(iDVDApplicationIdentity);
        focusFinderWindow(iDVDWindow);
        return;
      }
      showIDVDWindow();
    }

    function hideIDVDWindow() {
      const iDVDWindow = getIDVDWindow();
      if (iDVDWindow && iDVDWindow.isConnected && !iDVDWindow.classList.contains('is-minimized')) {
        minimizeFinderWindow(iDVDWindow);
      }
    }

    function quitIDVDWindow() {
      const iDVDWindow = getIDVDWindow();
      if (iDVDWindow && iDVDWindow.isConnected) {
        closeFinderWindow(iDVDWindow);
      }
    }

