    function showDocumentsWindow() {
      if (adoptExistingFinderWindow(document.getElementById('documents-window'))) {
        return;
      }

      const documentsDirectory = virtualFileSystem.root.children.find(
        (fileSystemObject) => fileSystemObject === documentsFileSystemObject
      );

      const documentsWindow = document.createElement('section');
      documentsWindow.id = 'documents-window';
      documentsWindow.className = 'finder-window documents-window';
      documentsWindow.setAttribute('role', 'dialog');
      documentsWindow.setAttribute('aria-labelledby', 'documents-window-title');
      documentsWindow.setAttribute('data-finder-window', 'true');
      finderWindowFileSystemObjects.set(documentsWindow, documentsDirectory);

      const { titleBar, content } = attachFilesystemFinderChrome(
        documentsWindow,
        'documents-window-title',
        documentsDirectory.name
      );

      const fileItems = [];
      const fileSystemObjects = getFileSystemObjectChildren(documentsDirectory).filter(
        (fileSystemObject) => fileSystemObject.type === 'file'
      );

      fileSystemObjects.forEach((fileSystemObject, fileIndex) => {
        const fileItem = document.createElement('div');
        fileItem.className = 'finder-file';
        setFinderItemIconLeft(fileItem, fileIndex, documentsWindow);
        fileItem.setAttribute('role', 'option');
        fileItem.setAttribute('aria-selected', 'false');
        fileItem.setAttribute('aria-label', fileSystemObject.name);
        finderItemFileSystemObjects.set(fileItem, fileSystemObject);
        fileItem.innerHTML = `
          <span class="finder-file-icon-art">
            <svg viewBox="0 0 64 68" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
              <defs>
                <linearGradient id="filePaper-${fileIndex}" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0" stop-color="#ffffff"/>
                  <stop offset="0.7" stop-color="#f1f2f3"/>
                  <stop offset="1" stop-color="#d7d9dc"/>
                </linearGradient>
                <linearGradient id="fileFold-${fileIndex}" x1="0" y1="0" x2="1" y2="1">
                  <stop offset="0" stop-color="#f8f9fa"/>
                  <stop offset="1" stop-color="#b9bec4"/>
                </linearGradient>
              </defs>
              <path d="M12 3.5h28.5L52 15v44.5c0 2.8-2.2 5-5 5H12c-2.8 0-5-2.2-5-5v-51c0-2.8 2.2-5 5-5z"
                    fill="url(#filePaper-${fileIndex})" stroke="#7f858b" stroke-width="1"/>
              <path d="M40.5 3.5V15H52z" fill="url(#fileFold-${fileIndex})" stroke="#8a9096" stroke-width="0.8" stroke-linejoin="round"/>
              <path d="M15 25h29M15 31h29M15 37h24M15 43h29M15 49h21"
                    fill="none" stroke="#8fa5b5" stroke-width="1.7" stroke-linecap="round" opacity="0.78"/>
              <path d="M15 20h18" stroke="#5d8cab" stroke-width="2" stroke-linecap="round" opacity="0.72"/>
              <path d="M10 7.5v49" stroke="#fff" stroke-width="1" opacity="0.72"/>
            </svg>
          </span>
          <span class="finder-file-label">${fileSystemObject.name}</span>
        `;
        attachFinderItemInfo(fileItem, fileSystemObject);
        attachFinderItemIconPreview(fileItem, fileSystemObject);

        fileItem.addEventListener('click', () => {
          selectDirectFinderItem(content, fileItem);
        });

        fileItem.addEventListener('dblclick', () => {
          openFileSystemObject(fileSystemObject);
        });

        fileItems.push(fileItem);
        content.appendChild(fileItem);
      });

      getFileSystemObjectChildren(documentsDirectory)
        .filter((fileSystemObject) => fileSystemObject.type === 'folder')
        .forEach((folderFileSystemObject) => {
          content.appendChild(createFinderFolderItem(
            content,
            folderFileSystemObject,
            getDirectFinderItems(content).length
          ));
        });
      appendUnrepresentedFileSystemItems(content, documentsDirectory);

      content.addEventListener('click', (event) => {
        if (event.target === content) {
          clearDirectFinderItemSelection(content);
        }
      });

      updateFinderWindowChrome(documentsWindow);
      document.body.appendChild(documentsWindow);
      enableWindowFocus(documentsWindow);
      makeWindowDraggable(documentsWindow, titleBar);
    }

