    document.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape') {
        return;
      }
      if (areTemporaryMenusOpen()) {
        closeAllMenuDropdowns();
        return;
      }
      if (isExposeActive) {
        exitExpose(null);
        return;
      }
      if (isDashboardOpen()) {
        closeDashboard();
      }
    });
