    function closeDesktopContextMenu() {
      desktopContextMenu.hidden = true;
    }

    function openDesktopContextMenu(event) {
      event.preventDefault();
      event.stopPropagation();
      closeAllMenuDropdowns();
      desktopContextMenu.hidden = false;
      desktopContextMenu.style.bottom = 'auto';
      const bounds = desktopContextMenu.getBoundingClientRect();
      const menuWidth = bounds.width || 168;
      const menuHeight = bounds.height || 131;
      const left = Math.min(Math.max(event.clientX, 2), Math.max(window.innerWidth - menuWidth - 4, 2));
      const top = Math.min(Math.max(event.clientY, 24), Math.max(window.innerHeight - menuHeight - 4, 24));
      desktopContextMenu.style.left = `${Math.round(left)}px`;
      desktopContextMenu.style.top = `${Math.round(top)}px`;
    }

    wallpaper.addEventListener('contextmenu', openDesktopContextMenu);
    document.getElementById('desktop-context-change-background').addEventListener('click', (event) => {
      event.stopPropagation();
      closeAllMenuDropdowns();
      showDesktopScreenSaverWindow();
    });
    desktopContextMenu.addEventListener('click', (event) => {
      event.stopPropagation();
      closeDesktopContextMenu();
    });
    desktopContextMenu.addEventListener('contextmenu', (event) => {
      event.stopPropagation();
    });
    document.addEventListener('click', (event) => {
      if (!desktopContextMenu.hidden && !event.target.closest('#desktop-context-menu')) {
        closeDesktopContextMenu();
      }
    });
    document.addEventListener('contextmenu', (event) => {
      if (!desktopContextMenu.hidden && !event.target.closest('#desktop-context-menu')) {
        closeDesktopContextMenu();
      }
    });
    macintoshHD.addEventListener('click', selectMacintoshHD);
    macintoshHD.addEventListener('dblclick', () => {
      clearTimeout(doubleClickFlashTimer);
      macintoshHD.classList.remove('is-double-clicked');
      showMacintoshHDWindow();

      requestAnimationFrame(() => {
        macintoshHD.classList.add('is-double-clicked');
        doubleClickFlashTimer = setTimeout(() => {
          macintoshHD.classList.remove('is-double-clicked');
        }, 180);
      });
    });
    macintoshHD.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        selectMacintoshHD();
      }
    });